(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["coding"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-repoformer-selective-retrieval-for-r-2024"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-1\">一 · 一个在线补全请求的现场</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-2\">二 · 旧方案的两条路线及其代价结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-3\">三 · 批调度层面的连锁反应</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-4\">四 · 为什么非改不可：质量与成本的双向挤压</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-5\">五 · 检索路径自身的隐藏成本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-6\">六 · 决策点前移的工程含义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-7\">七 · 触发率即成本：选择性检索在真实服务里的失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-8\">八 · 请求长度分布：两条路径塑造的双峰形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-9\">九 · 并发与批大小：按路径分桶而非统一组批</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-10\">十 · SLO 应按路径分别设定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-11\">十一 · 长尾：误判样本与超长拼接</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-12\">十二 · 方案反过来限制负载：阈值与预算的闭环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-13\">十三 · 前缀缓存与索引侧的负载耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-14\">十四 · 双路径负载画像：触发率如何决定显存、批形与 SLO 分界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-15\">十五 · 两条路径的 kernel 形态差异</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-16\">十六 · 数据类型：FP16/BF16 到 FP8 再到 NVFP4</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-17\">十七 · 累加精度与误差累积</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-18\">十八 · Blackwell 特性：tcgen05、TMEM、2-SM MMA</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-19\">十九 · 公式逐项与路径核算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-20\">二十 · 算子选择的工程落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-21\">二十一 · 选择性检索的算子边界：两条路径的精度与代价核算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-22\">二十二 · 两条路径的显存账本为何必须分开记</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-23\">二十三 · 分页与碎片：长短混批的真实代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-24\">二十四 · 前缀复用：为什么只有无检索路径吃得到</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-25\">二十五 · 压缩与卸载：KV 的量化与分层</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-26\">二十六 · HBM3e 容量怎么算：一个可复算的预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-27\">二十七 · 监控项与工程判断的落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-28\">二十八 · 两条路径的显存账本与失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-29\">二十九 · 两条路径的调度异构性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-30\">三十 · chunked prefill 与检索路径的预填峰值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-31\">三十一 · 优先级、抢占与尾延迟的压制</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-32\">三十二 · 分离式预填/解码在两条路径上的映射</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-33\">三十三 · 前缀缓存、批组成与容量规划的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-34\">三十四 · 分桶组批与路径级 SLO：选择性检索在调度层的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-35\">三十五 · 两条路径的并行切分不是同一个问题</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-36\">三十六 · NVLink 5 与 NVSwitch：域内带宽决定 TP 上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-37\">三十七 · All-to-All 与 EP：MoE 生成器的通信形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-38\">三十八 · PP 与 DP：流水线气泡和副本数的取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-39\">三十九 · NIXL 传输与分离式预填/解码的通信账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-40\">四十 · 通信何时成为瓶颈：按路径核算的判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-41\">四十一 · 选择性检索在并行拓扑上的边界与代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-42\">四十二 · 精度塌陷：漏检与误检的双向代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-43\">四十三 · OOM 与显存碎片：两条路径混跑的账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-44\">四十四 · 批抖动与尾延迟：按路径设 SLO</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-45\">四十五 · 静默降级：没有报错的质量滑坡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-46\">四十六 · 监控闭环与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-47\">四十七 · 双路径的失效边界：从阈值漂移到静默降级</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-48\">四十八 · 口径先行：把“选择性”拆成可测的四个量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-49\">四十九 · 硬件档位与 batch：两条路径不能共用一张组批表</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-50\">五十 · 指标怎么读：TTFT/TPOT 的分母是谁</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-51\">五十一 · 哪些提升不可比：五类常见错位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-52\">五十二 · 阈值标定的实测口径：把选择器当被测件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-53\">五十三 · 索引与缓存成本：不进延迟口径就会漏账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-54\">五十四 · 基准口径：两条路径不能共用一把尺</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-55\">五十五 · 迁移到别的代码模型：解耦带来的可移植性与其代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-56\">五十六 · 跨领域迁移：检索信号从“定义”变成“惯例”时失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-57\">五十七 · 规模上限：触发率与索引新鲜度决定天花板</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-58\">五十八 · 与低延迟机制的联合边界：前缀缓存与投机解码的适配条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-59\">五十九 · 不适用的场景与判断清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-repoformer-selective-retrieval-for-r-2024-sec-60\">六十 · 迁移与边界：换模型、换仓库、换负载时要动什么</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:577px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 577.0 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"495.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求进入后先取当前文件局部窗口与光标前缀，构成选择器输入。</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"495.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">选择器输出是否需要检索的二值决策及置信度，低置信样本走无检索快速路径。</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"495.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">需要检索时在仓库级索引上召回候选代码片段，按相关性打分排序。</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"495.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">对候选片段做过滤、去重与预算截断，控制拼接后的总 token 数。</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"495.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">生成器在选定上下文上做约束解码，输出补全并回填缓存供后续请求复用。</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-1\">一 · 一个在线补全请求的现场</h3>\n<p>设想一个托管在 GB200 NVL72 机架上的仓库级补全服务：IDE 插件在每次按键停顿约 300 毫秒后发出请求，携带光标前缀与当前文件局部窗口。请求到达调度器时，最刺眼的不是模型算力，而是上下文预算的分配方式。旧栈的主流做法是把当前文件窗口之外再拼上一批跨文件片段——固定窗口检索、或干脆把整个仓库的相关目录全量拼接。一个中等规模仓库里，跨文件定义、接口声明与调用点很容易把提示推到数万 token 量级，预填阶段要在 SM100 的 tcgen05 上把这些 token 全部过一遍注意力，KV cache 按层按头线性膨胀，显存占用与预填延迟同时抬升。更糟的是，绝大多数补全请求其实只需要当前文件内的局部信息——补一个循环体、补一个字段访问——却被无关的跨文件片段稀释了信号，生成质量反而下降。这就是这篇论文要处理的现场：不是模型不够强，而是上下文管理没有决策点。</p>\n<p>把这条请求链路拆开看，代价分布很不均匀。预填算力随拼接 token 数近似线性增长，KV cache 占用与上下文长度成正比，而解码阶段的自回归步数由补全长度决定、与上下文长度弱相关。于是长上下文的主要代价落在预填与显存上，而不是解码。对在线服务而言，这意味着尾延迟由长上下文请求主导，吞吐由显存中能同时驻留多少条 KV 决定。旧方案没有区分请求类型，所有请求共享同一套上下文拼接策略，等于让简单请求为复杂请求的预算买单。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-2\">二 · 旧方案的两条路线及其代价结构</h3>\n<p>论文之前的推理栈大致分两类。第一类是固定窗口检索：按文件名、路径距离或符号匹配召回固定数量的片段，无条件拼接。第二类是全量拼接：把仓库索引中与当前文件有依赖关系的文件整体塞进提示，寄望于长上下文模型自行消化。两者共同的缺陷是缺乏按样本判断“是否值得检索”的机制——检索决策是静态的、与请求内容无关的。</p>\n<p>固定窗口检索的代价是噪声与预算浪费。召回数量固定意味着简单请求也被迫携带无关片段，相关性过滤缺失时这些片段挤占生成长度预算，并在注意力中稀释真正相关的信号。全量拼接的代价更直接：预填算力与 KV cache 占用随仓库规模增长，长上下文请求在批中占据大量显存，导致可并发的请求数下降。用公式刻画单请求的预填代价，设拼接上下文长度为 <span class=\"formula\">$$L$$</span>、层数为 <span class=\"formula\">$$N_l$$</span>、头数为 <span class=\"formula\">$$N_h$$</span>、头维度为 <span class=\"formula\">$$d_h$$</span>，则 KV cache 的字节数近似为：</p>\n<div class=\"formula\">$$\\mathrm{KV}_{\\text{bytes}} \\approx 2 \\cdot N_l \\cdot N_h \\cdot d_h \\cdot L \\cdot b_{\\text{elem}}$$</div>\n<p>其中系数 2 对应 K 与 V 两份，<span class=\"formula\">$$b_{\\text{elem}}$$</span> 是每元素字节数。这个式子说明：上下文长度是 KV 占用的唯一可调杠杆，而旧方案把这个杠杆固定在最大值附近。预填算力则大致随 <span class=\"formula\">$$L^2$$</span> 在注意力部分增长、随 <span class=\"formula\">$$L$$</span> 在线性层增长，长上下文请求因此在预填阶段吃掉不成比例的 SM 时间。</p>\n<p>具体例子：一个补全请求只需在当前文件内补一个 <span class=\"formula\">$$for$$</span> 循环的边界条件，旧栈仍按固定窗口召回五个跨文件片段，拼接后上下文从数百 token 涨到数千 token。预填时间随之抬升，KV 占用按上式线性放大，而生成质量并未改善——这些片段与循环边界无关。反过来，一个需要跨文件接口定义的补全，固定窗口可能召回的是同目录下无关的工具函数，关键定义漏检，补全直接出错。两类失败在同一套静态策略下无法同时修复。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-3\">三 · 批调度层面的连锁反应</h3>\n<p>旧方案的代价不止于单请求。连续批处理把不同长度的请求混在同一批中，长上下文请求的 KV 占用会压缩批的剩余显存，短请求被迫等待或降批。显存碎片在长短混批时尤为明显：一条数万 token 的请求与若干数百 token 的请求同批，前者独占大块连续显存，后者填充缝隙，批的整体利用率下降。尾延迟由批中最长的那条请求决定，而旧栈无法预知哪些请求会变长——因为检索是无条件的，所有请求都可能被拼成中等长度以上。</p>\n<p>前缀缓存本可以缓解短请求的重复预填，但旧栈的上下文拼接是静态且随文件变化的，缓存键不稳定，命中率被压低。更关键的是，调度器没有路径信息可用于分桶：它不知道一条请求是“自足”还是“需要跨文件”，只能按统一策略组批。这直接导致容量规划失真——平均上下文长度被长请求拉高，按平均值配置显存档位会在尾延迟上失守，按峰值配置则浪费显存。工程上必须回答的问题是：能否在请求进入生成器之前，就以低成本判断它属于短路径还是长路径，从而让批调度按路径分桶、让 KV 预算按路径核算。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-4\">四 · 为什么非改不可：质量与成本的双向挤压</h3>\n<p>旧方案的问题在于它把两个目标绑死在一起。要提升复杂补全的质量，就得扩大召回、增加拼接长度，代价是预填算力与显存；要压低简单补全的延迟，就得缩短上下文，代价是复杂补全缺关键定义。固定窗口与全量拼接都在这条曲线上选了一个静态点，无法按样本移动。仓库级补全的请求分布是重尾的：多数请求自足，少数请求依赖跨文件符号。用单一策略服务重尾分布，必然在多数请求上过度支付、在少数请求上支付不足。</p>\n<p>论文的核心主张正是把这个静态点变成按样本的决策变量。设选择器输出一个分数 <span class=\"formula\">$$s(x)$$</span>，阈值 <span class=\"formula\">$$\\tau$$</span> 决定路径：</p>\n<div class=\"formula\">$$\\hat{y}=\\begin{cases}f_{\\theta}(x), &amp; s(x)&lt;\\tau\\\\ f_{\\theta}\\big(x\\oplus \\mathrm{TopK}_{k\\le B}(R(x))\\big), &amp; s(x)\\ge\\tau\\end{cases}$$</div>\n<p>其中 <span class=\"formula\">$$R(x)$$</span> 是仓库索引上的召回，<span class=\"formula\">$$B$$</span> 是 token 预算，<span class=\"formula\">$$\\oplus$$</span> 表示过滤去重后的拼接。这个式子的工程含义是：上下文长度从常量变成随机变量，其期望由检索触发率决定。触发率偏低则平均上下文短、预填成本低，但漏检跨文件定义的风险上升；触发率偏高则回到旧方案的成本结构。阈值因此不是超参数装饰，而是容量规划的直接输入——它决定了平均 KV 占用与预填算力的期望值。</p>\n<p>具体到部署，这意味着两件事必须分开核算。无检索路径的上下文短，预填算力低，KV 占用小，适合前缀缓存复用，批可以组得更大；检索路径要承担召回、相关性过滤与拼接的额外开销，上下文长度随请求变化，缓存命中率低，尾延迟更高。把两条路径混在一起按统一 SLO 考核，会让短路径的余量被长路径的尾延迟吃掉。旧栈没有这条分界线，所以它的 SLO 只能按最坏情况设定，容量被系统性高估。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-5\">五 · 检索路径自身的隐藏成本</h3>\n<p>即便触发检索，旧方案也没有把检索当作有成本的操作来管理。召回候选片段后直接拼接，缺少相关性过滤与去重，弱相关片段与重复内容进入上下文，既稀释信号又挤占预算。过滤与去重本身有算力开销：打分、排序、按预算截断都要在请求路径上完成，这段延迟不体现在生成器的预填时间里，却真实计入端到端尾延迟。仓库索引的构建与更新成本同样未被旧栈量化——仓库频繁变更时，索引失效与重建会周期性抬高峰值负载。</p>\n<p>一个具体的工程判断是：检索路径的成本必须与无检索路径分开核算，否则会把选择性检索当成免费收益。召回、过滤、拼接三段各有延迟，且拼接后的上下文长度分布比无检索路径更宽，批调度需要按路径分别组批以避免长短混批造成的显存碎片。这正是旧栈缺失的调度维度——它只有一条路径，也就没有分桶的依据。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-6\">六 · 决策点前移的工程含义</h3>\n<p>把“是否检索”前移为一个轻量选择器的二值决策，改变的不只是上下文长度，而是整条推理栈的调度形态。选择器只需读取光标前缀与局部窗口，输入短、算力低，可以在请求进入生成器之前完成判定，并把路径标签传给调度器。调度器据此分桶组批：短路径请求共享前缀缓存、组大批；长路径请求单独成批、按预算截断后的上下文长度核算显存。KV 预算从“按最坏情况预留”变成“按路径分布预留”，容量规划的输入从单一峰值变成触发率与预算两个可监控参数。</p>\n<p>代价也随之转移：选择器误判成为主要失败模式。漏检导致复杂补全缺关键定义，误检则引入噪声并推高预填与显存代价。阈值与仓库分布耦合——同一阈值在不同仓库上的触发率差异明显，需按仓库标定并持续监控置信度分布。这些是旧方案不曾面对的问题，因为它们根本没有决策点；而一旦有了决策点，监控项就必须包括检索触发率、平均拼接 token 数、选择器置信度分布与分路径尾延迟。工程上的判断很直接：上下文长度从常量变成可控变量之后，容量规划的自由度与监控的责任同时增加，阈值标定不再是离线调参，而是持续运行的运维动作。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-7\">七 · 触发率即成本：选择性检索在真实服务里的失效边界</h3>\n<p>先看一个具体的在线场景：一个中等规模团队的 IDE 补全后端，单集群承载数千并发会话，请求以光标前缀加局部窗口为主。若沿用固定窗口检索，每个请求都要付出召回、过滤、拼接的固定开销，即便补全一个局部变量赋值也要拖着一批无关片段进入提示；若沿用全量拼接，预填算力与 KV cache 随仓库规模线性抬升，长上下文把真正相关的定义稀释掉。两条旧路径的共同缺陷不是检索质量，而是<strong>缺少按样本判断“是否值得检索”的决策点</strong>——上下文长度成了与请求无关的常量，容量规划只能按最坏情况留显存档位。</p>\n<p>Repoformer 把这件事变成条件分支：选择器先看局部窗口，输出是否检索的二值决策与置信度，仅当判定需要跨文件信息时才走召回路径。设选择器打分 <span class=\"inline-math\">s(x)</span>、阈值 <span class=\"inline-math\">τ</span>，则平均上下文长度可写成触发率 <span class=\"inline-math\">p=P(s(x)≥τ)</span> 的函数：</p>\n<div class=\"formula\">$$\\bar{L}=p\\cdot\\big(L_{\\text{loc}}+B\\big)+(1-p)\\cdot L_{\\text{loc}}$$</div>\n<p>其中 <span class=\"inline-math\">B</span> 是检索路径的拼接预算。这条式子说明阈值不是质量旋钮而是<strong>成本旋钮</strong>：<span class=\"inline-math\">p</span> 偏低则预填算力与 KV 占用下降，但漏检跨文件定义的概率上升；<span class=\"inline-math\">p</span> 偏高则等于退回全量拼接。更关键的是 <span class=\"inline-math\">p</span> 与仓库分布强耦合——同一阈值在定义密集的基础库仓库与脚本型仓库上的触发率差异明显，落地必须按仓库标定并持续监控置信度分布。</p>\n<table class=\"mini\"><thead><tr><th>路径</th><th>上下文长度</th><th>预填算力</th><th>KV 复用</th><th>尾延迟特征</th></tr></thead><tbody><tr><td>无检索</td><td>短，仅局部窗口</td><td>低</td><td>前缀缓存命中率高</td><td>稳定，适合统一 SLO</td></tr><tr><td>检索</td><td>局部窗口 + 预算截断片段</td><td>高，含召回与过滤开销</td><td>上下文随请求变化，需按请求重建</td><td>召回与拼接抬升尾部，需单独设目标</td></tr></tbody></table>\n<p>系统代价必须分路径核算，不能把选择性检索当成免费收益。检索路径的召回、相关性过滤、去重与截断都占算力与带宽，且上下文每次不同导致前缀缓存命中率低；无检索路径的短前缀反而适合缓存复用。两条路径上下文长度差异明显，混批会同时造成显存碎片与尾延迟抬升——工程判断是<strong>按路径分桶组批、按路径分别设定 SLO</strong>，并把检索触发率、平均拼接 token 数、选择器置信度分布列为容量规划的一级输入。失效边界也很清楚：选择器误判是主要失败模式，漏检导致缺关键定义，误检则引入噪声并额外付出预填与显存代价；此外仓库索引的构建与更新成本、频繁变更下的缓存失效策略，材料均未量化，部署侧需自行补齐。</p>\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-8\">八 · 请求长度分布：两条路径塑造的双峰形态</h3>\n<p>仓库级补全的请求长度不是单一分布，而是被选择性检索切成两段。无检索路径的输入由光标前缀与局部窗口构成，长度偏短且集中在窄区间；检索路径则在短前缀之上叠加召回片段、过滤去重后的拼接块，长度显著抬升。部署侧真正要测的不是“平均长度”，而是两条路径各自的长度分位数：P50、P90、P99 与最大值。平均长度会把双峰抹平成无意义的中间值，用它做显存档位规划必然偏差。</p>\n<p>触发率 <span>r</span> 与两段长度共同决定平均上下文长度：</p>\n<div class=\"formula\">$$\\bar{L}=r\\cdot L_{\\text{ret}}+(1-r)\\cdot L_{\\text{noretr}},\\qquad \\mathrm{Var}(L)=r(1-r)\\,(L_{\\text{ret}}-L_{\\text{noretr}})^2$$</div>\n<p>方差项说明为什么双峰分布对批调度不友好：<span>r</span> 接近 0.5 且两段长度差距大时，方差最大，混批的显存占用按最长请求对齐，短请求被迫陪跑。举例：同一批里既有 2k token 的自足补全，又有拼接后 16k 的跨文件补全，前者占用的 KV 槽位被后者拉高，吞吐按最长样本结算。可核查口径：按路径分别记录 token 长度直方图（分桶宽度固定）、触发率、拼接后总 token 数的 P99，以及被预算截断的请求占比。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-9\">九 · 并发与批大小：按路径分桶而非统一组批</h3>\n<p>连续批处理的前提是请求可被自由拼装，但两条路径的上下文长度差异明显，统一组批会让调度器在“填满批次”与“控制尾延迟”之间反复妥协。工程做法是按路径分桶：无检索桶追求大 batch 与高吞吐，检索桶按长度再细分（如短拼接、长拼接两级），桶内组批、桶间按权重轮转。这样显存碎片被限制在桶内，长请求不会拖住短请求的迭代步。</p>\n<p>批大小的上界由 KV 预算反推，而非拍脑袋：设单请求平均 KV 占用 <span>\\(M_{\\text{kv}}(L)\\)</span>、可用显存 <span>\\(M_{\\text{free}}\\)</span>、权重与激活预留 <span>\\(M_{\\text{res}}\\)</span>，则</p>\n<div class=\"formula\">$$B_{\\max}\\approx\\frac{M_{\\text{free}}-M_{\\text{res}}}{\\max_{i\\in\\text{batch}} M_{\\text{kv}}(L_i)}$$</div>\n<p>分母取批内最长请求，正是混批代价的数学表达。检索桶里若出现一条超长拼接，整桶的 <span>\\(B_{\\max}\\)</span> 被压到个位数。代价体现在吞吐上：无检索桶可以跑到较高并发，检索桶的 token 吞吐被预填算力与 KV 带宽双重限制。可核查口径：每桶的实测 batch 大小分布、桶内最长与最短请求长度比、因显存不足被拒绝入批的请求数、每步迭代的 token 产出。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-10\">十 · SLO 应按路径分别设定</h3>\n<p>统一 SLO 是混批场景下最常见的误配。检索路径多出召回、相关性过滤、去重与拼接四段开销，尾延迟天然高于无检索路径；若用同一 TP99 目标约束两条路径，调度器会为了压检索路径的尾延迟而牺牲无检索路径的吞吐，或者反过来让检索请求长期违约。正确做法是双 SLO：无检索路径给紧的 TP99（交互式补全对首 token 敏感），检索路径给较宽的 TP99 但单独监控其超时率。</p>\n<p>尾延迟的来源要拆开核算。检索路径的延迟可近似分解为</p>\n<div class=\"formula\">$$T_{\\text{ret}}=T_{\\text{sel}}+T_{\\text{recall}}+T_{\\text{filter}}+T_{\\text{prefill}}(L_{\\text{ret}})+T_{\\text{decode}}$$</div>\n<p>其中 <span>\\(T_{\\text{prefill}}\\)</span> 随拼接长度超线性增长，是尾延迟的主项；<span>\\(T_{\\text{recall}}\\)</span> 与 <span>\\(T_{\\text{filter}}\\)</span> 是索引侧开销，与仓库规模相关而非与模型相关。举例：一次触发检索的补全，其预填阶段要处理数倍于无检索路径的 token，若与十条短请求混批，短请求的迭代步被拉长，交互体验下降。可核查口径：分路径的 TTFT 与 TPOT 分位数、检索各阶段耗时占比、SLO 违约请求的路径归属与长度分布。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-11\">十一 · 长尾：误判样本与超长拼接</h3>\n<p>长尾有两个来源，且都不在平均指标里显形。其一是选择器误判：阈值偏低时，本可自足的样本被误检进入检索路径，凭空多出召回与预填开销；阈值偏高时，需要跨文件定义的样本漏检，走短路径生成，质量下降但不体现在延迟上。误检推高成本，漏检推高质量风险，两者的代价方向相反，必须分开监控。可核查口径：抽样人工标注选择器决策的正确率、误检率与漏检率、误检样本的平均拼接长度、漏检样本的补全被回滚或修改的比例。</p>\n<p>其二是超长拼接。相关性过滤与去重之后仍可能剩下接近预算上限的片段集合，这类请求在检索桶里是长尾，单条就能压垮整桶的批大小。预算截断是硬约束，但截断本身有代价：被截掉的片段若含关键定义，补全质量受损。工程上应对长尾做隔离——把超过某长度阈值的请求单独成批或降级到串行路径，避免其污染主桶的迭代节奏。代价是这部分请求的吞吐下降、显存占用峰值抬升，需要在容量规划里单独留出水位。可核查口径：拼接长度超过阈值的请求占比、这些请求的 TP99、截断发生的频次与被截片段的相关性得分分布。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-12\">十二 · 方案反过来限制负载：阈值与预算的闭环</h3>\n<p>负载塑造方案，方案也塑造负载。选择器阈值 <span>τ</span> 与检索预算 <span>B</span> 是两个直接改写请求分布的旋钮：调低 <span>τ</span> 抬高触发率 <span>r</span>，平均上下文长度与 KV 占用同步上升，预填算力吃紧；调高 <span>τ</span> 压低 <span>r</span>，显存压力缓解但漏检风险累积。预算 <span>B</span> 则截断拼接长度的上界，直接决定检索路径的长度分布形状与 P99。</p>\n<p>这意味着容量规划不能把 <span>r</span> 当外生常量。给定显存与算力约束，可反解出可承受的触发率上限：</p>\n<div class=\"formula\">$$r_{\\max}\\approx\\frac{C_{\\text{budget}}-\\bar{L}_{\\text{noretr}}\\cdot N}{\\big(\\bar{L}_{\\text{ret}}-\\bar{L}_{\\text{noretr}}\\big)\\cdot N}$$</div>\n<p>其中 <span>\\(C_{\\text{budget}}\\)</span> 是单位时间可承担的上下文 token 总量，<span>N</span> 是请求速率。这个式子把“阈值调到多少”从调参问题变成容量问题：先定 <span>\\(r_{\\max}\\)</span>，再按仓库分布标定 <span>τ</span>，并持续监控实际触发率是否漂移。举例：某仓库定义分散、跨文件引用密集，同一阈值下触发率明显高于另一仓库，若不按仓库重新标定，前者的预填成本会持续超预算。可核查口径：按仓库统计的触发率、阈值与触发率的对应曲线、预算截断比例、单位请求的平均上下文 token 数随时间的漂移。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-13\">十三 · 前缀缓存与索引侧的负载耦合</h3>\n<p>无检索路径的短前缀适合前缀缓存复用：同一文件的连续补全请求共享前缀，KV 可直接命中，预填算力被摊薄。检索路径则因拼接片段随请求变化，前缀命中率低，KV 需按请求重建，缓存收益有限。这形成一种反向激励：缓存命中率高的路径恰好是成本低的路径，缓存收益无法抵消检索路径的开销，两条路径的成本差被进一步放大。</p>\n<p>索引侧同样被负载牵动。仓库频繁变更时，索引更新与缓存失效的频次随请求速率上升，召回阶段的延迟抖动进入尾延迟。增量索引策略与失效窗口的选择，取决于变更频率与请求速率之比，而非索引算法本身。可核查口径：分路径的前缀缓存命中率、检索路径 KV 重建比例、索引更新频次与召回延迟的 P99、缓存失效后首批请求的延迟抬升幅度。这些口径与触发率、长度分位数共同构成一套可复核的测量面，缺任何一项都无法判断成本究竟落在预填、KV 还是索引侧。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-14\">十四 · 双路径负载画像：触发率如何决定显存、批形与 SLO 分界</h3>\n<p>Repoformer 的部署负载不是一个分布，而是两个被选择器阈值 τ 切开的分布。无检索路径的输入近似为“光标前缀 + 局部窗口”，长度集中且偏短；检索路径的输入是“局部窗口 ⊕ 过滤截断后的 TopK 片段”，长度由预算 B 硬性封顶但方差大。可核查的测量口径必须按路径分别采集：对每个请求记录 <em>路径标签</em>（s(x)&lt;τ 与否）、<em>选择器置信度</em>、<em>拼接后总 token 数</em>、<em>召回候选数与过滤后保留数</em>、<em>首 token 延迟与端到端延迟</em>、<em>KV 峰值占用</em>。平均上下文长度可由触发率直接推算：设触发率为 r，短路径均值 L₀、检索路径均值 L₁，则容量规划用的期望上下文长度为</p>\n<div class=\"formula\">$$\\bar{L}=(1-r)\\,L_{0}+r\\,L_{1},\\qquad L_{1}\\le L_{0}+B$$</div>\n<p>这条式子说明阈值不是质量旋钮而是<strong>成本旋钮</strong>：r 每上升一点，预填算力与 KV cache 占用就按 (L₁−L₀) 的差额线性抬升，而 B 决定了抬升的上界。工程上应把 r 当作一等监控指标，按仓库分别统计——同一 τ 在定义密集的基础库与自足的业务脚本上触发率差异极大，全局单一阈值必然在某些仓库上过检、在另一些仓库上漏检。可核查的做法是：对每个仓库采样一批请求，离线标注“是否真的需要跨文件定义”，画出触发率-漏检率的权衡曲线，再定 τ；上线后持续监控选择器置信度分布的低分尾部，因为误判主要发生在置信度接近 τ 的样本上。</p>\n<p>批调度是这套方案最容易被低估的代价点。两条路径的上下文长度差异明显，若按到达顺序混批，一个检索路径的长请求会把整批的显存占用抬到长上下文的档位，短请求被迫等待，尾延迟被放大；同时变长拼接导致批内序列长度参差，显存碎片与填充浪费同时出现。正确做法是按路径分桶组批，并在桶内按长度分档，使每批的 KV 预算可预估。代价是调度器复杂度上升与短路径的批填充率下降——短请求单独组批时更容易凑不满批，吞吐换尾延迟。前缀缓存的收益同样分路径：无检索路径的前缀在相似光标位置间高度重复，缓存命中率高、可显著摊薄预填；检索路径的拼接上下文随请求变化，命中率低，KV 需按请求重建，这部分预填算力无法被缓存摊销。因此容量模型应写成两条独立的成本线，而不是一条混合平均线。</p>\n<p>SLO 必须按路径分别设定。检索路径多出召回、相关性打分、过滤去重与拼接四段串行开销，尾延迟天然更高；用统一阈值考核会逼使系统压低 τ 以减少慢请求，反而牺牲复杂补全的质量。可核查的 SLO 口径是分路径的 P50/P99 首 token 延迟与端到端延迟，外加一个跨路径的<strong>误判代价指标</strong>：漏检样本（应检索却走短路径）的补全被回退或人工修正的比例，以及误检样本（不应检索却触发）相对短路径的额外预填 token 数与延迟增量。失效条件很明确：当仓库索引陈旧、增量更新滞后时，检索路径召回的是过期定义，过滤环节无法识别语义漂移，此时提高 r 只会把噪声灌进上下文并挤占生成长度预算；当选择器被低比特量化后判定准确率下降，误判率上升会同时污染两条路径的成本核算。索引构建与更新的算力、以及仓库高频变更下的缓存失效策略，材料未给出量化，落地时必须单列预算，否则选择性检索会被当成免费收益而低估总成本。</p>\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-15\">十五 · 两条路径的 kernel 形态差异</h3>\n<p>选择性检索在算子层面制造了一个容易被忽视的事实：无检索路径与检索路径不是同一套 kernel 的两种输入长度，而是两种不同的计算形态。无检索路径的上下文是光标前的局部窗口，长度短且前缀稳定，其预填阶段几乎全部落在 GEMM 密集区，注意力矩阵小到可以被单 CTA 完整容纳，KV 写入量低，适合用前缀缓存把历史 token 的 K/V 直接复用。检索路径则相反：拼接后的上下文由若干不连续片段组成，注意力掩码带段边界，预填长度随召回结果波动，KV cache 需按请求重建。对 Blackwell 上的实现者，这意味着两条路径应走不同的 kernel 选择：短路径优先走低延迟的小 tile 配置并把权重常驻，长路径走大 tile、高 occupancy 的预填 kernel，把算力吃满。</p>\n<p>代价可以直接写成两条路径的预填 FLOPs 对比。设无检索上下文长度为 <span>L₀</span>、检索路径拼接长度为 <span>L₁</span>、模型隐藏维 <span>d</span>、层数 <span>N</span>，则单请求预填的近似算力为：</p>\n<div class=\"formula\">$$C_{\\text{prefill}} \\approx N \\cdot \\big(4L d^2 + 2L^2 d\\big)$$</div>\n<p>第一项是 QKV 与投影的线性部分，随 <span>L</span> 线性增长；第二项是注意力打分与加权，随 <span>L²</span> 增长。当 <span>L₁</span> 明显大于 <span>L₀</span> 时，二次项主导，检索路径的预填代价按长度平方放大——这正是选择器阈值必须被当作容量参数而非精度参数的原因。举例：某仓库补全请求局部窗口只有数百 token，触发检索后拼接至数千 token，二次项放大的倍数远超线性项，预填时间与 KV 占用同步抬升，而这一切只发生在被判定为“需要跨文件信息”的样本上。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-16\">十六 · 数据类型：FP16/BF16 到 FP8 再到 NVFP4</h3>\n<p>生成器权重的精度选择直接决定显存带宽压力。Blackwell 的第五代 Tensor Core 在 FP8 与 NVFP4 上有原生通路，前者是 8 位浮点、每通道一个缩放因子，后者是 4 位微缩放格式，以更细的块级缩放换取更低的位宽。对代码补全这类输出长度中等、对数值稳定性敏感的任务，工程判断是分层的：生成器主体用 BF16 保动态范围，注意力与 MLP 的权重矩阵可下探到 FP8 以换取带宽，NVFP4 更适合放在权重常驻、batch 较大的解码阶段，而预填阶段因激活动态范围宽，激进低比特会放大误差。</p>\n<p>误差可以用量化噪声的相对幅度来刻画。对权重 <span>W</span> 与量化版本 <span>\\(\\hat{W}\\)</span>，逐元素误差 <span>\\(\\varepsilon = \\|\\hat{W}-W\\|/\\|W\\|\\)</span>，其经线性层传播后对输出的影响近似为：</p>\n<div class=\"formula\">$$\\frac{\\|\\Delta y\\|}{\\|y\\|} \\lesssim \\kappa(W)\\cdot \\varepsilon,\\qquad \\kappa(W)=\\frac{\\sigma_{\\max}}{\\sigma_{\\min}}$$</div>\n<p><span>\\(\\kappa(W)\\)</span> 是权重矩阵的条件数，<span>\\(\\sigma_{\\max}\\)</span>、<span>\\(\\sigma_{\\min}\\)</span> 为奇异值极值。条件数大的层对量化误差更敏感，代码模型里注意力输出投影与 MLP 下投影常属此类。因此低比特不应全局一刀切，而应按层做敏感度排序，把 FP8/NVFP4 留给条件数小、带宽占比高的层。代价侧：位宽减半意味着同一显存容量可容纳更大 batch 或更长 KV，解码阶段的带宽瓶颈随之缓解，但若误差抬升导致重试或补全被拒，端到端收益会被抵消。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-17\">十七 · 累加精度与误差累积</h3>\n<p>低比特输入并不等于低比特累加。Tensor Core 在 FP8/NVFP4 输入下仍以更高精度累加，这是控制误差的关键机制。若把累加也压到低精度，长归约链上的舍入误差会随 <span>K</span> 维累加步数增长。设每次累加的舍入误差上界为 <span>u</span>、归约长度为 <span>K</span>，最坏情况误差按 <span>Ku</span> 线性累积，而随机舍入下按 <span>\\(\\sqrt{K}u\\)</span> 增长：</p>\n<div class=\"formula\">$$\\|\\delta\\|_{\\text{worst}} \\le K u,\\qquad \\|\\delta\\|_{\\text{rms}} \\approx \\sqrt{K}\\,u$$</div>\n<p>对 <span>K</span> 达数千的 MLP 上投影，两种界差一个量级，这解释了为何累加精度必须高于输入精度。工程上的具体做法是：矩阵乘在 Tensor Core 内以 FP32 累加，归约结果再按需降回 BF16 写回；对检索路径这种上下文长、注意力打分归约长的形态，尤其不能省累加位宽。代价是累加器占用寄存器与 TMEM 空间，2-SM MMA 下两个 SM 共享一次 MMA 的累加结果，累加精度提高会压缩可并行的 tile 数，需要在 occupancy 与数值稳定之间取平衡。</p>\n<p>例子：同一段需要跨文件定义的补全，在 FP8 输入加 FP32 累加下输出稳定；若把累加降到 FP16，长上下文注意力打分的尾部会出现打分抖动，导致约束解码在候选 token 间反复摇摆，表现为生成变慢而非明显错误——这类退化只能靠监控选择器置信度分布与重试率间接发现。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-18\">十八 · Blackwell 特性：tcgen05、TMEM、2-SM MMA</h3>\n<p>tcgen05 是 Blackwell 上面向 Tensor Core 的指令族，把矩阵乘的调度从 warp 级协作上移到 CTA 对级，配合 TMEM（Tensor Memory）作为累加器与操作数的专用暂存。TMEM 的价值在于把累加结果从寄存器文件挪到近计算单元的专用存储，减少寄存器压力，使大 tile 的 MMA 能在不牺牲 occupancy 的前提下展开。对推理的直接含义是：预填阶段可以用更大的 <span>M×N</span> tile 吃满算力，而解码阶段因 batch 小、<span>M</span> 维窄，tile 效率下降，需靠权重常驻与 KV 分块读取维持带宽利用率。</p>\n<p>2-SM MMA 让一对 SM 协同完成一次矩阵乘，操作数与累加结果跨 SM 共享，等效于把 tile 尺寸翻倍而保持单 SM 的寄存器预算。伪代码思路如下：</p>\n<div class=\"formula\">$$\\text{for } k \\text{ in } K\\text{-tiles}:\\ \\ \\text{TMEM} \\mathrel{+}= \\text{MMA}_{2\\text{SM}}(A_k, B_k)$$</div>\n<p>每次迭代把一对 K 分块的乘积累加到 TMEM，跨 SM 的同步由硬件完成，软件只需保证 A、B 的分块布局对齐。代价侧：2-SM MMA 要求两个 SM 的 tile 形状匹配，批调度若把长短上下文请求混批，短请求凑不满 tile 会浪费一半 SM 的算力；这正是按路径分桶组批在算子层的物理理由。举例：无检索路径的短请求若与检索路径的长请求同批，前者在 2-SM MMA 下形成“半空”tile，算力利用率下降，尾延迟被长请求拖长，而分桶后两条路径各自凑满 tile，预填吞吐与尾延迟同时改善。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-19\">十九 · 公式逐项与路径核算</h3>\n<p>把前述公式落到部署核算上，需要区分两条路径各自的成本项。预填算力 <span>\\(C_{\\text{prefill}}\\)</span> 的线性项对应权重读取，受显存带宽约束；二次项对应注意力，受 Tensor Core 算力与 TMEM 容量约束。解码阶段每步的算力近似为：</p>\n<div class=\"formula\">$$C_{\\text{decode}} \\approx N\\cdot 2 d^2 \\cdot B$$</div>\n<p><span>B</span> 为批内并发序列数。解码是带宽受限而非算力受限：权重读取量固定，batch 越大摊薄越明显，因此 NVFP4 在解码阶段的收益最直接。但检索路径的 KV 长度随请求变化，KV 读取量随 <span>B</span> 与平均上下文长度增长，若前缀缓存命中率低，KV 带宽会成为新的瓶颈。工程判断是：无检索路径靠前缀缓存把 KV 读取压到接近零，检索路径则需按请求重建 KV，两条路径的带宽账必须分开记。</p>\n<p>误差项则通过 <span>\\(\\kappa(W)\\cdot\\varepsilon\\)</span> 进入质量核算：选择器本身可低比特量化以降低判定开销，但其输出是二值决策加置信度，量化误差会直接移动阈值附近样本的判定结果，进而改变检索触发率与平均上下文长度。这意味着选择器的量化误差不是纯精度问题，而是容量问题——触发率漂移会连锁改变预填算力与 KV 占用。具体例子：选择器以 FP8 量化后，阈值附近的低置信样本判定翻转，触发率上升，平均拼接 token 数增加，预填与显存代价同步抬升，而补全质量未必改善。因此选择器量化需与阈值标定联合评估，监控项应包含置信度分布与触发率的联动漂移。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-20\">二十 · 算子选择的工程落点</h3>\n<p>把以上机制收束为可执行的算子决策：短路径走小 tile、低延迟预填 kernel，权重常驻显存，KV 复用前缀缓存；长路径走大 tile、2-SM MMA 与 TMEM 累加，注意力掩码按段边界构造，避免跨片段的无意义打分。数据类型上，生成器主体 BF16、带宽敏感层 FP8、解码权重 NVFP4，累加一律 FP32，按层条件数排序决定下探深度。批调度按路径分桶，保证 2-SM MMA 的 tile 被凑满。监控三项：检索触发率、平均拼接 token 数、选择器置信度分布，三者联动漂移即是算子层代价变化的先行信号。这套决策的落点不在单个 kernel 的最优，而在两条路径各自不被对方的形态拖累——混批与全局统一精度是两个最常见的代价泄漏点。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-21\">二十一 · 选择性检索的算子边界：两条路径的精度与代价核算</h3>\n<p>把选择性检索落到 Blackwell 上，第一件事是承认它不是一个 kernel 问题，而是两个 kernel 集合的问题。无检索路径的输入是短前缀，注意力长度落在几百 token 量级，算子形态接近常规短序列解码：GEMM 的 M 维小、K 维由隐藏宽度决定，瓶颈在权重带宽而非算力，FP16/BF16 权重配合 FP8 激活即可让第五代 Tensor Core 吃满；此时 tcgen05 的 TMEM 累加器主要承担的是把 softmax 前的 QK^T 与 PV 两段 MMA 的中间结果留在片上，减少往返 HBM 的次数。检索路径则相反，拼接后上下文被预算截断到 B 个 token，预填阶段的 GEMM 变成大 M、长 K 的形态，2-SM MMA 的收益才真正显现——两个 SM 共享一次权重读取、把 tile 做大，直接压低每 token 的权重带宽摊薄。两条路径的算术强度差异可达一个数量级以上，用同一套 tile 配置去覆盖两者，必然在其中一条上浪费。</p>\n<p>数值精度上要分开决策。生成器的精度直接决定补全质量，代码补全对标识符和运算符的逐位正确性敏感，FP8 甚至 NVFP4 的权重量化在长上下文预填时误差会被注意力放大：softmax 对 logits 的微小扰动会改变注意力分布的尾部，而尾部恰恰是跨文件定义所在的位置。一个可操作的判据是看累加精度与缩放粒度，NVFP4 的块级缩放（每 16 元素一组共享指数）在 K 维很长时误差累积近似正比于块数，可写成</p>\n<div class=\"formula\">$$\\varepsilon_{\\text{acc}} \\approx \\sqrt{N_{\\text{blk}}}\\cdot \\delta_q,\\qquad N_{\\text{blk}}=\\left\\lceil \\frac{K}{16}\\right\\rceil$$</div>\n<p>其中 δ_q 是单块量化步长，N_blk 是沿 K 维的块数。检索路径的 K 被预算 B 拉长，N_blk 随之上升，误差按平方根增长；而无检索路径 K 短，同样的 NVFP4 配置误差可控。这解释了为什么工程上常见的做法是：短路径激进量化换带宽，长路径回到 FP8 或 BF16 保精度，代价是长路径的权重带宽翻倍、预填延迟上升。选择器本身可以低比特量化，它的输出是二值决策加置信度，量化误差只影响阈值附近的样本，代价是误判率抬升而非逐位错误——这是两条路径精度策略必须解耦的根本原因。</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>无检索路径</th><th>检索路径</th></tr></thead><tbody><tr><td>上下文长度</td><td>短前缀，KV 占用低</td><td>预算 B 截断，KV 随 B 线性增长</td></tr><tr><td>算子形态</td><td>小 M 解码，权重带宽受限</td><td>大 M 预填，2-SM MMA 收益显著</td></tr><tr><td>精度策略</td><td>可激进量化</td><td>需保 FP8/BF16 防注意力尾部失真</td></tr><tr><td>缓存</td><td>前缀缓存命中率高</td><td>上下文随请求变化，需重建 KV</td></tr></tbody></table>\n<p>失效条件集中在阈值与预算的耦合上。阈值 τ 偏低会让大量自足样本误入检索路径，预填算力与 KV 占用被无关片段推高，同时相关性过滤若不够狠，噪声片段挤占生成长度预算，模型在长上下文里反而丢失光标附近的局部信号；阈值偏高则漏检跨文件定义，补全退化为局部猜测。预算 B 的截断同样有边界：截断按相关性排序做，但相关性打分与生成器实际需要的定义未必一致，排序错位时关键片段被切掉，误差不体现在数值精度上而体现在语义缺失上。批调度层面，两条路径混批会让短请求等待长请求的预填，尾延迟被长上下文样本主导，显存碎片来自两种 KV 尺寸交错分配；按路径分桶组批是必须的，代价是短路径的批利用率下降，需要靠前缀缓存复用来补偿。</p>\n<p>工程判断落在监控项上：检索触发率、平均拼接 token 数、选择器置信度分布三者共同决定平均上下文长度，也就是预填算力与 KV 占用的期望值；把这几个量与两条路径各自的尾延迟分开统计，才能在阈值漂移时定位是误检推高了预填成本，还是漏检拖低了质量。仓库索引的构建与增量更新成本不在 kernel 侧，但它决定了检索路径的召回延迟下限，频繁变更的仓库上缓存失效策略缺失会让检索路径的 P99 失去可预测性。</p>\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-22\">二十二 · 两条路径的显存账本为何必须分开记</h3>\n<p>Repoformer 的推理管线把一次补全拆成互斥的两支：选择器判定自足的样本走 <span class=\"inline-code\">f_θ(x)</span> 短上下文路径，判定需要跨文件的样本走 <span class=\"inline-code\">f_θ(x ⊕ TopK(R(x)))</span> 拼接路径。这两支的显存结构不是同一张表按比例缩放，而是三个账本项各自变化方向不同：权重（静态、与路径无关）、激活（随预填 token 数线性增长）、KV cache（随上下文长度与并发数增长，且检索路径因上下文逐请求变化而无法跨请求复用）。把两条路径的显存混在一张总表里做容量规划，等于用平均值掩盖了尾部的真实峰值——检索路径的单请求 KV 可能是无检索路径的数倍，而它的到达率又由选择器阈值决定，是个统计量而非固定值。</p>\n<p>因此本部分的显存预算必须写成“按路径分桶、按触发率加权”的形式。设单卡可用显存为 <span class=\"inline-code\">M</span>，权重占用 <span class=\"inline-code\">W</span>，每 token 的 KV 字节数为 <span class=\"inline-code\">k</span>，无检索路径平均上下文长度为 <span class=\"inline-code\">L₀</span>、检索路径为 <span class=\"inline-code\">L₁</span>，触发率为 <span class=\"inline-code\">p</span>，两条路径各自的并发批大小为 <span class=\"inline-code\">b₀</span>、<span class=\"inline-code\">b₁</span>，则稳态显存约束为：</p>\n<div class=\"formula\">$$W + k\\cdot\\big(b_0 L_0 + b_1 L_1\\big) + A_{\\text{act}} \\le M$$</div>\n<p>其中 <span class=\"inline-code\">A_act</span> 是预填阶段的峰值激活，它不与 KV 共享同一块增长曲线——预填激活随单次前向的 token 数上升，而 KV 随驻留请求数累积。工程上常见的错误是把 <span class=\"inline-code\">b₀</span> 与 <span class=\"inline-code\">b₁</span> 设成同一个数，然后在检索路径上撞到 OOM；正确做法是按 <span class=\"inline-code\">p</span> 反推 <span class=\"inline-code\">b₁</span> 的上界，让 <span class=\"inline-code\">b₁·L₁</span> 不超过 KV 池中划给长上下文分区的份额。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-23\">二十三 · 分页与碎片：长短混批的真实代价</h3>\n<p>KV cache 的分配粒度决定了混批是否可行。若按请求最大长度预留连续显存，一个 <span class=\"inline-code\">L₁</span> 的检索请求会独占一整块，即使它实际只用了其中一部分，块内剩余空间也无法被短请求利用——这就是内部碎片。分页式 KV（把 KV 切成固定大小的 page，按需追加、逻辑地址映射到物理页）把碎片从“块内浪费”转成“页级浪费”，浪费上界收敛到不足一页。Repoformer 的两条路径长度差异明显，正是分页机制收益最直接的场景：短请求只占一两页，长请求按需追加，物理页池可以在两条路径间共享。</p>\n<p>但分页不是免费的。页表查询增加寻址开销，页数越多、注意力核访问 KV 的间接层越深，长上下文下的带宽效率会被页表遍历稀释。更关键的是批调度层面：把 <span class=\"inline-code\">L₀</span> 与 <span class=\"inline-code\">L₁</span> 的请求塞进同一个连续批，解码步的注意力核必须按批内最长上下文配置，短请求被迫在长序列的 KV 上做无效扫描，尾延迟被抬升。按路径分桶组批的本质是把“批内长度方差”压到接近零，代价是两条路径各自可能凑不满批，牺牲一部分批利用率换稳定的尾延迟。这是一个明确的工程取舍：吞吐换尾延迟确定性。</p>\n<p>具体例子：一个仓库补全服务同时收到 30 个短前缀请求与 4 个触发检索的长请求。混批时批内最长上下文由那 4 个请求决定，30 个短请求的解码步都要承担长 KV 的带宽成本；分桶后短批以高并发跑满，长批以小并发独占一个 KV 分区，两条路径的 SLO 可以分别设定。代价是长批的批利用率低，GPU 算力在长批上闲置更多——这部分闲置必须由触发率 <span class=\"inline-code\">p</span> 的统计稳定性来摊销，若 <span class=\"inline-code\">p</span> 随仓库波动剧烈，长批的到达间隔就会抖动。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-24\">二十四 · 前缀复用：为什么只有无检索路径吃得到</h3>\n<p>前缀缓存（prefix caching）复用的是相同 token 前缀对应的 KV 块，命中条件是该前缀在历史请求中出现过且未被驱逐。无检索路径的输入是光标前的局部窗口，同一文件内连续编辑时前缀高度重叠，命中率高；检索路径的输入是“局部窗口 ⊕ 召回片段”，召回结果随查询变化，前缀在拼接点之后立刻分叉，可复用的只有拼接点之前的局部窗口部分，命中率被拼接位置截断。这意味着两条路径的 KV 复用收益不在一个量级，容量规划时不能给检索路径假设同样的缓存命中率。</p>\n<p>复用带来的显存收益是可复算的：设前缀长度为 <span class=\"inline-code\">L_p</span>、总上下文为 <span class=\"inline-code\">L</span>，命中后需新建的 KV 只有 <span class=\"inline-code\">(L − L_p)·k</span> 字节，节省比例为 <span class=\"inline-code\">L_p / L</span>。无检索路径上 <span class=\"inline-code\">L_p</span> 接近 <span class=\"inline-code\">L₀</span>，节省比例高；检索路径上 <span class=\"inline-code\">L_p</span> 只是拼接点前的局部窗口，<span class=\"inline-code\">L₁</span> 又因召回片段而变长，节省比例被显著压低。工程判断：给检索路径预留的 KV 池应按“无复用”估算，把前缀缓存当成无检索路径的额外余量，而不是两条路径共享的通用折扣。</p>\n<p>复用还有一致性代价：仓库文件变更会使局部窗口的前缀失效，缓存条目必须按文件版本打标签并在变更时失效，否则会复用陈旧 KV 产生错误补全。材料未给出索引更新与缓存失效策略的量化，这一块在部署时需自行设计版本化键。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-25\">二十五 · 压缩与卸载：KV 的量化与分层</h3>\n<p>KV cache 压缩有两条正交的轴：数值精度与结构稀疏。数值轴上，KV 按低比特存储（如 FP8）可直接把 <span class=\"inline-code\">k</span> 减半，代价是注意力打分的数值误差累积，长上下文下误差随层数放大，需在生成质量上单独评估；结构轴上，按注意力权重淘汰低贡献 token 的 KV 条目，或按头/层做共享，能在不改变数值格式的前提下削减驻留量，但淘汰决策本身要读一遍注意力权重，属于额外带宽开销。Repoformer 的检索路径上下文长、噪声片段多，结构压缩的收益理论上更大——被过滤掉的弱相关片段本就不该占据 KV，但过滤发生在拼接前，压缩发生在拼接后，两者不能互相替代。</p>\n<p>卸载（offload）把冷 KV 页搬到主机内存或远端存储，按需回迁。它的收益边界由 PCIe/NVLink 带宽与回迁延迟决定：解码步每步都要读全量 KV，若命中率不高，回迁带宽会成为新的瓶颈，把显存节省换成延迟上升。对检索路径而言，长上下文请求的 KV 在解码期间几乎每步都被访问，卸载的命中率低，实际可用性有限；对无检索路径的短请求，KV 驻留时间短，卸载窗口也短。因此卸载更适合作为“突发长请求的溢出缓冲”，而不是稳态容量手段。</p>\n<p>带宽瓶颈的位置需要分清：预填阶段是算力密集（矩阵乘为主），解码阶段是带宽密集（每步读全量权重与 KV）。检索路径把更多 token 塞进预填，推高的是预填算力与激活峰值；而它更长的 KV 让解码阶段的每步带宽需求上升，解码吞吐按每步读取字节数反比下降。容量规划若只看显存不看带宽，会在长上下文高并发时撞到 HBM 带宽墙而非容量墙。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-26\">二十六 · HBM3e 容量怎么算：一个可复算的预算</h3>\n<p>HBM3e 的容量按堆栈计：单堆栈容量乘以每 GPU 的堆栈数得到单卡容量，这是权重、激活、KV 三者共享的物理上限。计算顺序应是自顶向下扣减：先扣权重（含量化后的字节数），再扣预填峰值激活（按最大单次前向 token 数估算），剩余部分才是 KV 池。KV 池再按路径分桶，用第一节的约束式反解 <span class=\"inline-code\">b₁</span> 的上界。</p>\n<p>可复算的预算模板如下（数值为结构示例，非实测）：</p>\n<table class=\"mini\">\n<thead>\n<tr><th>账本项</th><th>计算式</th><th>随路径变化</th></tr>\n</thead>\n<tbody>\n<tr><td>权重</td><td>参数量 × 每参数字节</td><td>不变</td></tr>\n<tr><td>预填激活</td><td>批内最大预填 token 数 × 每 token 激活字节 × 层数因子</td><td>检索路径更高</td></tr>\n<tr><td>KV（无检索）</td><td>b₀ × L₀ × k × (1 − 前缀命中率)</td><td>命中率高，实际占用低</td></tr>\n<tr><td>KV（检索）</td><td>b₁ × L₁ × k</td><td>无复用，按满额计</td></tr>\n<tr><td>碎片余量</td><td>页大小 × 并发请求数上界</td><td>分页后收敛到页级</td></tr>\n</tbody>\n</table>\n<p>反解步骤：给定 <span class=\"inline-code\">M</span>、<span class=\"inline-code\">W</span>、<span class=\"inline-code\">A_act</span>、<span class=\"inline-code\">k</span>、<span class=\"inline-code\">L₀</span>、<span class=\"inline-code\">L₁</span>、<span class=\"inline-code\">p</span>，先由无检索路径的并发目标定 <span class=\"inline-code\">b₀</span>，剩余 KV 预算除以 <span class=\"inline-code\">L₁·k</span> 得到 <span class=\"inline-code\">b₁</span> 上界；再用 <span class=\"inline-code\">p</span> 校验长批的到达率是否会让 <span class=\"inline-code\">b₁</span> 长期打满。若 <span class=\"inline-code\">b₁</span> 上界小于 1，说明该显存档位无法承载检索路径，必须降 <span class=\"inline-code\">L₁</span>（收紧检索预算 <span class=\"inline-code\">B</span>）或提高 KV 压缩比，而不是靠调阈值把 <span class=\"inline-code\">p</span> 压到零——后者等于放弃选择性检索的质量收益。</p>\n<p>具体例子：某仓库补全服务在单卡上把权重与激活扣完后剩固定 KV 池，无检索路径以较高并发跑短前缀并吃到前缀缓存折扣；检索路径按满额 KV 估算只能容纳个位数并发。此时容量规划的杠杆不在显存，而在检索预算 <span class=\"inline-code\">B</span>：把拼接 token 上限收紧，<span class=\"inline-code\">L₁</span> 下降直接抬高 <span class=\"inline-code\">b₁</span> 上界，代价是可能截断关键定义。这个取舍必须由选择器置信度分布与漏检率监控来驱动，而不是拍一个固定预算。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-27\">二十七 · 监控项与工程判断的落点</h3>\n<p>显存账本要变成可运维的系统，需要把第一节公式里的每个变量都变成可观测指标：检索触发率 <span class=\"inline-code\">p</span>、两条路径的平均与 P99 上下文长度、KV 池的分区占用率、前缀缓存命中率（分路径统计）、页级碎片率、预填峰值激活。其中 <span class=\"inline-code\">p</span> 是唯一同时驱动显存、预填算力与尾延迟的杠杆变量，它的漂移会直接改写容量结论——同一阈值在不同仓库上触发率差异大，必须按仓库标定并持续监控，否则一次仓库结构变化就能让长批打满 KV 分区。</p>\n<p>工程判断落在两处。其一，检索路径的 KV 按无复用满额计，无检索路径的前缀缓存收益只作为余量，不参与长上下文分区的容量承诺；其二，当 <span class=\"inline-code\">b₁</span> 上界逼近 1 时，优先动检索预算 <span class=\"inline-code\">B</span> 与 KV 压缩比，而不是动选择器阈值——压阈值是把显存问题转嫁成质量问题，且这种转嫁在监控上表现为漏检率上升而非显存下降，容易被误读为“系统变稳了”。真正稳的做法是让两条路径各自持有独立的 KV 分区与独立的 SLO，把混批的尾延迟放大效应从架构上消除。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-28\">二十八 · 两条路径的显存账本与失效边界</h3>\n<p>Repoformer 的显存账本不能按单一模型算，必须按路径分账。无检索路径的 KV 占用近似为 <span class=\"formula\">$$M_{\\text{kv}}=2\\cdot L\\cdot H_{\\text{kv}}\\cdot d_h\\cdot b\\cdot T_{\\text{short}}\\cdot s$$</span>（层数、KV 头数、头维、批、短上下文长度、字节数），预填算力随 <span class=\"formula\">$$T_{\\text{short}}$$</span> 线性走；检索路径则把 <span class=\"formula\">$$T_{\\text{short}}$$</span> 换成截断后的拼接长度 <span class=\"formula\">$$T_{\\text{ret}}\\le B$$</span>，并额外承担召回、相关性过滤与去重的算力，以及随请求变化的上下文导致的 KV 重建。工程判断很直接：触发率 <span class=\"formula\">$$r$$</span> 决定平均上下文长度 <span class=\"formula\">$$\\bar{T}=(1-r)T_{\\text{short}}+rT_{\\text{ret}}$$</span>，而 <span class=\"formula\">$$r$$</span> 由选择器阈值 <span class=\"formula\">$$\\tau$$</span> 直接控制——阈值偏低推高预填与 KV 占用，偏高则漏检跨文件定义。容量规划应以 <span class=\"formula\">$$\\bar{T}$$</span> 而非最长请求做基线，再按路径分桶留出尾延迟余量。</p>\n<p>失效条件集中在三处。其一，前缀缓存复用只对无检索路径成立：短前缀稳定、命中率高；检索路径的上下文随请求变化，缓存命中率低、需按请求重建 KV，若把两条路径混在同一前缀缓存池里，检索路径会持续冲刷短请求的缓存条目，反而抬高整体预填成本。其二，混批是显存碎片与尾延迟的直接来源，长短上下文请求同批会让批内最大长度决定整批 KV 分配，短请求被迫按长请求的 <span class=\"formula\">$$T_{\\text{ret}}$$</span> 占位；必须按路径分桶组批，并分别设定 SLO。其三，选择器误判的代价不对称：漏检只损失质量，误检则同时付出召回算力、噪声污染上下文、挤占生成长度预算三重代价，因此阈值标定应偏向保守，并按仓库分布持续监控触发率漂移。</p>\n<table class=\"mini\"><thead><tr><th>路径</th><th>KV 规模</th><th>预填算力</th><th>缓存复用</th><th>主要代价</th></tr></thead><tbody><tr><td>无检索</td><td>随 <span class=\"formula\">$$T_{\\text{short}}$$</span></td><td>低</td><td>高，前缀稳定</td><td>漏检风险</td></tr><tr><td>检索</td><td>随 <span class=\"formula\">$$T_{\\text{ret}}\\le B$$</span></td><td>高，含召回过滤</td><td>低，按请求重建</td><td>误检噪声、尾延迟</td></tr></tbody></table>\n<p>可复算的预算做法：给定批 <span class=\"formula\">$$b$$</span>、字节 <span class=\"formula\">$$s$$</span> 与模型 KV 几何，先按 <span class=\"formula\">$$\\bar{T}$$</span> 算平均 KV，再按分桶后的批大小分别核算两条路径的峰值，权重与激活另计但通常不随 <span class=\"formula\">$$T$$</span> 线性增长，KV 才是主项。仓库索引的构建与更新成本未量化，频繁变更时需增量索引与失效策略，否则检索路径的召回延迟会侵蚀分桶收益；选择器低比特量化对判定准确率的影响也需单独评估，不能默认量化后阈值不变。</p>\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-29\">二十九 · 两条路径的调度异构性</h3>\n<p>Repoformer 的推理管线在调度层面不是一条队列，而是两条特征迥异的路径。无检索路径的输入是光标前局部窗口，token 数短且稳定；检索路径的输入是局部窗口加上召回、过滤、去重、预算截断后的片段集合，长度随请求波动且分布右偏。这意味着同一套连续批处理（continuous batching）策略套在两条路径上会产生结构性错配：短请求被长请求拖住，长请求又被短请求的完成节奏打断。工程上的第一判断是<strong>按路径分桶组批</strong>，把无检索请求与检索请求放进独立的调度队列，各自维护批大小与 token 预算。分桶的代价是两条队列各自的批利用率可能都不满——尤其在检索触发率处于中间区间时，两条队列都凑不出理想批大小，GPU 占用率下降。因此分桶不是免费的，它换来的是尾延迟可控，付出的是平均吞吐的折损。</p>\n<p>连续批处理的收益来自迭代级调度：每个 decode step 结束时把已完成的序列踢出、把排队的序列填进来，使批的组成随迭代演化。对无检索路径，序列长度接近，踢出与填入的节奏整齐，批内 token 数方差小，SM 占用平稳。对检索路径，序列长度差异大，短序列先完成、长序列继续占用 KV 页，批内出现“空洞”——已完成序列释放的 KV 页无法被新请求立即复用，因为新请求的 prefill 需要一次性占用大块连续显存。这就是混批造成显存碎片的机制来源，不是隐喻：分页式 KV 管理下，页的分配粒度与请求的 prefill 峰值需求不匹配时，碎片以页为单位累积。</p>\n<div class=\"formula\">$$\\text{批内有效占用}=\\frac{\\sum_{i\\in \\text{batch}} L_i^{\\text{ctx}}+L_i^{\\text{gen}}}{\\max_{i} L_i^{\\text{ctx}}+\\max_{i} L_i^{\\text{gen}}}\\cdot \\frac{1}{N_{\\text{batch}}}$$</div>\n<p>这个比值刻画了混批的浪费程度：分子是批内实际 token 总量，分母是按最长请求对齐后的容量。无检索路径该比值接近 1，检索路径则随长度方差下降。举例：一批四条检索请求，上下文长度分别为 2k、4k、8k、16k token，按最长对齐后有效占用不足一半，剩余容量在 decode 阶段全程闲置，直接体现为吞吐损失与单位 token 功耗上升。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-30\">三十 · chunked prefill 与检索路径的预填峰值</h3>\n<p>检索路径的 prefill 是延迟尖峰的主要来源。拼接后的上下文可能达到数万 token，一次性 prefill 会在短时间内吃满算力与显存带宽，把同批其他请求的 decode 迭代挤到后面，形成队头阻塞。chunked prefill 把长 prefill 切成固定 token 预算的块，与 decode 迭代交错执行，使单次迭代的算力需求有上界。机制上，调度器每个迭代从 prefill 队列取一个 chunk、从 decode 队列取若干序列，拼成一个总算力预算受控的混合批。对 Repoformer，这带来一个额外好处：检索路径的 prefill chunk 可以与无检索路径的 decode 迭代共批，把短路径的 decode 空隙填满，提升整体 SM 利用率。</p>\n<p>代价是首 token 时延（TTFT）被拉长。chunk 切得越细，单次迭代的算力峰值越低、批利用率越平滑，但一个长上下文请求要跨越更多迭代才能完成 prefill，TTFT 随 chunk 数线性增长。这是一个显式的取舍参数：chunk 大小是 TTFT 与吞吐之间的旋钮。对代码补全场景，TTFT 直接决定用户感知的响应速度，而检索路径恰恰是用户已经等待了检索召回的那部分请求，TTFT 再被 chunk 拉长会叠加成明显的体感延迟。工程判断是给检索路径设一个 chunk 上限，超过上限的长请求走独占批而非与 decode 混批，用吞吐换 TTFT 的确定性。</p>\n<p>另一个机制细节：chunked prefill 要求 KV 写入按 chunk 增量进行，前缀缓存（prefix caching）的复用粒度也随之变成 chunk 级。无检索路径的短前缀命中率高，缓存块可跨请求复用；检索路径的上下文随请求变化，缓存命中率低，chunk 级写入意味着即使前缀部分相同，也要按块重新计算并写入。这直接抬高了检索路径的显存带宽占用——KV 写入量与 chunk 数成正比，而非与请求数成正比。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-31\">三十一 · 优先级、抢占与尾延迟的压制</h3>\n<p>尾延迟在两条路径上的成因不同，压制手段也不同。无检索路径的尾延迟来自排队：请求短、完成快，但突发流量下队列深度瞬间抬升，P99 由排队时间主导。检索路径的尾延迟来自长尾上下文：少数请求的拼接长度远超均值，prefill 与 decode 都更慢，且它们占用的 KV 页在完成后才释放，期间挤压后续请求的可用显存。统一 SLO 在这两种成因下失效——按无检索路径标定的延迟目标会让检索路径持续违约，按检索路径标定则让无检索路径的容量被过度预留。</p>\n<p>抢占（preemption）是压制尾延迟的硬手段。当显存不足以容纳新请求的 prefill 峰值时，调度器可以选择换出（swap）或重算（recompute）低优先级序列的 KV。重算的代价是丢弃已计算的 KV 并在稍后重新 prefill，换出的代价是 KV 页写入主机内存再读回，两者都消耗带宽。对 Repoformer，抢占策略应按路径区分：无检索路径的序列短，重算成本低，适合作为被抢占方；检索路径的序列长，重算代价高，应给予更高的驻留优先级，避免其 KV 被反复丢弃重建。优先级不应按请求到达顺序，而应按“已投入的 prefill 算力”排序——已 prefill 大半的长请求被抢占，等于把最贵的部分扔掉重来。</p>\n<p>具体例子：一条 16k token 的检索请求已完成 12k 的 prefill，此时一条新请求到达需要 8k 的 prefill 峰值显存。若按 FIFO 抢占，长请求被换出，12k 的算力作废；若按已投入算力排序，调度器选择等待或抢占一条刚起步的短请求，长请求继续推进。前者的尾延迟体现在长请求的完成时间翻倍，后者体现在短请求的排队时间上升。选择哪一种，取决于该仓库的检索触发率——触发率高时长请求占比大，保护长请求；触发率低时短请求是主流，抢占长请求更划算。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-32\">三十二 · 分离式预填/解码在两条路径上的映射</h3>\n<p>分离式（disaggregated）预填/解码把 prefill 与 decode 拆到不同的 GPU 池，prefill 池算力密集、decode 池显存带宽密集，各自按需扩缩。对 Repoformer，这种拆分与两条路径的异构性天然对齐：无检索路径的 prefill 极短，几乎可以全部放到 decode 池本地完成，省去一次 KV 传输；检索路径的 prefill 长且算力峰值高，放到专用 prefill 池能避免污染 decode 池的迭代节奏。KV 从 prefill 池传到 decode 池走的是池间互联，传输量等于上下文长度乘以层数与头数，对长上下文请求这是一笔可观的带宽开销，必须在收益核算里计入。</p>\n<p>传输代价的机制：KV 传输时间与上下文长度成正比，与互联带宽成反比。检索路径的上下文长度是变量，传输时间也是变量，这使 decode 池的接收侧出现到达时间抖动，进而影响连续批处理的批组成稳定性。工程上的缓解手段是按路径设传输优先级，短上下文的 KV 先传、先入批，长上下文的 KV 分块流式传输，decode 侧按块启动计算，不必等全部 KV 到齐。这与 chunked prefill 的思路同构：把一个大延迟事件切成多个小延迟事件，用流水线掩盖。</p>\n<p>代价核算要分开做：无检索路径若走分离式，KV 传输开销相对其极短的 prefill 算力可能不划算，本地 prefill 更优；检索路径若不走分离式，长 prefill 会周期性打断 decode 池的批稳定性，尾延迟抬升。因此分离式的收益是路径相关的，不能对整个管线一刀切。判断依据是检索触发率与平均拼接长度：触发率高、拼接长，分离式收益明显；触发率低，分离式引入的传输与调度开销可能超过其收益。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-33\">三十三 · 前缀缓存、批组成与容量规划的耦合</h3>\n<p>前缀缓存是压低无检索路径延迟的直接手段：同一文件的光标前缀在连续补全请求间高度重叠，缓存命中后 prefill 退化为增量计算，TTFT 显著下降。机制上，缓存以块为单位索引前缀的 KV，命中判定按块粒度做最长公共前缀匹配。对 Repoformer，无检索路径的短前缀命中率高，缓存块复用率高；检索路径的上下文由召回片段拼成，片段集合随请求变化，最长公共前缀通常只覆盖局部窗口部分，缓存命中率低。这意味着两条路径的缓存收益不对称，容量规划不能按统一命中率估算。</p>\n<p>批组成与缓存命中相互影响：连续批处理下，批内序列的前缀若高度重叠，缓存块可在批内共享，显存占用下降；若前缀各异，每个序列独立占用缓存块，显存占用上升。检索路径的批内前缀差异大，缓存共享率低，这直接抬高了其单位请求的显存成本。容量规划的关键输入因此不是平均上下文长度，而是<strong>按路径加权的显存占用分布</strong>：检索触发率乘以检索路径的平均 KV 占用，加上无检索路径的占用，再叠加缓存块的碎片余量。</p>\n<p>工程判断落在阈值标定上。选择器阈值决定检索触发率，触发率决定两条路径的请求比例，比例决定批组成与缓存命中率，最终决定显存与尾延迟。阈值不是一次性调参，而是随仓库分布漂移的持续监控量：同一阈值在不同仓库上的触发率差异大，需按仓库标定并跟踪触发率、平均拼接 token 数、选择器置信度分布与分路径尾延迟。漏检关键定义表现为补全错误率上升，误检表现为预填成本与显存占用上升——两者在监控上可区分，前者看质量指标，后者看资源指标。把这两类失败模式分开计量，是把选择性检索从“看起来免费”变成可核算收益的前提。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-34\">三十四 · 分桶组批与路径级 SLO：选择性检索在调度层的边界</h3>\n<p>选择性检索把请求劈成两条长度分布截然不同的路径，调度器若仍按统一批处理，混批就是最先失效的地方。无检索路径的上下文是光标前缀加局部窗口，长度偏短且前缀稳定；检索路径则要叠加召回、过滤、去重与预算截断后的片段，长度随请求浮动。两者同批时，批内最大序列长度由检索路径决定，短请求被迫按长请求的显存档位分配 KV 页，形成显存碎片，同时预填阶段被长样本拖长，短请求的完成时延被无谓抬高。工程上应按路径分桶：无检索桶走小批高频，检索桶走大批低频，桶间不共享批。代价是桶内批大小受各自到达率限制，低触发率时检索桶可能长期凑不满批，吞吐让位于尾延迟。</p>\n<p>分桶后，容量规划的关键输入是检索触发率 <span class=\"inline-math\">r</span>，它由选择器阈值 <span class=\"inline-math\">τ</span> 直接决定。平均上下文长度可写成两路径的加权：</p>\n<div class=\"formula\">$$\\bar{L}=(1-r)\\,L_{\\text{none}}+r\\,L_{\\text{ret}},\\qquad \\mathrm{KV}_{\\text{avg}}\\propto \\bar{L}\\cdot b$$</div>\n<p>阈值偏低推高 <span class=\"inline-math\">r</span>，预填算力与 KV 占用同步上涨；阈值偏高则漏检跨文件定义，补全质量在复杂样本上塌陷。更麻烦的是 <span class=\"inline-math\">r</span> 与仓库分布耦合：同一阈值在不同仓库上的触发率差异明显，按全局标定的阈值迁到新仓库即失效，必须按仓库标定并持续监控置信度分布。尾延迟的压制不能靠调大批，而要靠路径级 SLO 分别设定——检索路径的召回与拼接开销使其 P99 天然高于无检索路径，用统一阈值考核只会逼调度器牺牲短路径的批大小。</p>\n<p>缓存策略同样按路径分裂。无检索路径的前缀在连续请求间高度重合，前缀缓存命中率高，KV 可复用；检索路径的上下文随召回结果变化，缓存命中率低，需按请求重建 KV，这部分重建成本必须计入检索路径的延迟预算而非摊到全局。选择器本身可低比特量化以压低判定开销，但量化对判定准确率的影响需单独评估，误判的两种方向代价不对称：漏检丢关键定义，误检引入噪声并额外付出预填与显存。仓库索引的构建与增量更新成本材料未量化，仓库频繁变更时缓存失效策略缺失，这使检索路径的延迟在索引刷新窗口内不可预测，调度器应把索引更新视为可抢占的低优先级后台任务，避免其与在线请求争抢显存带宽。</p>\n<table class=\"mini\"><thead><tr><th>路径</th><th>上下文特征</th><th>组批策略</th><th>缓存</th><th>尾延迟来源</th></tr></thead><tbody><tr><td>无检索</td><td>短、前缀稳定</td><td>小批高频</td><td>前缀复用</td><td>混批抬升</td></tr><tr><td>检索</td><td>长、随请求浮动</td><td>大批低频</td><td>按请求重建</td><td>召回+拼接+索引刷新</td></tr></tbody></table>\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-35\">三十五 · 两条路径的并行切分不是同一个问题</h3>\n<p>Repoformer 的推理管线被选择器切成两段异构负载：无检索路径是“短前缀 + 生成”，检索路径是“召回 + 过滤 + 拼接 + 长上下文生成”。在 Blackwell 上做并行切分时，这两条路径的瓶颈位置不同，不能套用同一套 TP/EP/PP/DP 配置。无检索路径上下文短、KV 占用低，单卡或小 TP 即可跑满，切分重点在 DP 上做吞吐；检索路径的预填阶段是长序列、算力密集，TP 切分能摊薄单卡预填时间，但 TP 组内每层都要做 All-Reduce，通信量与隐藏维度成正比，序列越长、TP 越大，All-Reduce 在预填阶段的占比越显著。工程判断是：按路径分别配置并行度，无检索路径用 DP 为主、TP=1 或 2，检索路径用 TP=4/8 并配合 EP 处理 MoE 生成器，两条路径的进程组隔离，避免一条路径的集合通信拖住另一条。</p>\n<p>具体机制上，SM100 的 tcgen05 MMA 与 TMEM 让单 SM 的矩阵吞吐抬升，但 2-SM MMA 需要成对 SM 协同，TP 切分时每张卡持有的权重分片要与 2-SM 的配对粒度对齐，否则会出现“切了 TP 却用不上 2-SM”的浪费。代价体现在预填延迟：TP 组内每层两次 All-Reduce，若跨 NVLink 域的 hop 数增加，单次集合通信的固定开销会吃掉算力收益。例子：一个触发检索的补全请求，拼接后上下文达到数万 token，预填算力需求远高于无检索路径的短前缀；此时若 TP 组跨了 NVSwitch 域边界，All-Reduce 的尾延迟会直接反映到首 token 时间上，而无检索路径的请求在同一时刻可能已经完成数批。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-36\">三十六 · NVLink 5 与 NVSwitch：域内带宽决定 TP 上限</h3>\n<p>Blackwell 的 NVL72 机柜把 72 颗 GPU 放进同一个 NVLink 域，NVLink 5 的单卡带宽与 NVSwitch 的全互联拓扑使得 TP/EP 的集合通信可以留在域内完成。对 Repoformer 而言，这意味着检索路径的 TP 组可以开到较大规模而不必跨域，All-Reduce 的带宽代价被压在域内；但一旦 TP 组或 EP 组跨出 NVSwitch 域，通信就要走更贵的路径，延迟与带宽同时恶化。机制上，NVSwitch 提供的是无阻塞的全互联交换，集合通信的算法选择（环形 vs 树形）会影响实际可达带宽：环形 All-Reduce 的通信量与 (2(N-1)/N)·数据量 成正比，N 为组内卡数，树形在低延迟场景更优但带宽利用率略低。</p>\n<div class=\"formula\">$$T_{\\text{AR}} \\approx \\frac{2(N-1)}{N}\\cdot\\frac{S}{B_{\\text{link}}} + L_{\\text{hop}}\\cdot \\lceil \\log_2 N \\rceil$$</div>\n<p>其中 S 为单层激活字节数，B_link 为链路有效带宽，L_hop 为每跳固定延迟。这个式子说明：TP 增大时通信量趋近于 2S（与 N 无关的上界），但跳数与固定延迟随 N 增长，所以 TP 的收益在某个 N 之后被延迟吃掉。对检索路径的长序列预填，S 很大，带宽项主导，TP 扩到域内上限仍有收益；对无检索路径的短序列解码，S 很小，延迟项主导，TP 扩大反而变慢。工程上应把无检索路径固定在单卡或 TP=2，把 TP 预算留给检索路径。例子：NVL72 内一个 8 卡 TP 组做长上下文预填，All-Reduce 走 NVSwitch 域内，带宽项可控；若把同一组拆到两个域，跨域 hop 的固定延迟会在每层叠加，预填时间显著抬升。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-37\">三十七 · All-to-All 与 EP：MoE 生成器的通信形态</h3>\n<p>若生成器是 MoE 结构，EP 切分引入的是 All-to-All 而非 All-Reduce：token 按路由结果被分发到持有对应专家的卡上，计算后再聚合回来。All-to-All 的通信量取决于路由的分散度——每个 token 被路由到 top-k 个专家，若专家均匀分布在 EP 组内，单 token 的发送量约为 k 份隐藏状态。Repoformer 的检索路径上下文长、token 多，All-to-All 的绝对通信量随序列长度线性增长，且路由不均衡会造成某些卡成为热点，尾延迟由最慢的那张卡决定。机制上，EP 组内需要做 capacity factor 限制与 token 丢弃/重排，否则热点卡的队列会拖垮整组。</p>\n<p>代价核算：All-to-All 的带宽需求与 EP 组规模、top-k、隐藏维度三者相乘，在 NVLink 域内尚可承受，跨域则迅速成为瓶颈。对 Repoformer 的部署含义是：检索路径的长上下文请求应尽量落在同一 NVLink 域内的 EP 组，避免跨域 All-to-All；无检索路径若也走 MoE，短序列的 All-to-All 固定开销占比高，可考虑把无检索路径路由到稠密模型或小 EP 组。例子：一个仓库级补全请求触发检索后拼接出长上下文，MoE 生成器在 EP=8 的组内做 All-to-All，若路由集中在少数专家，热点卡的发送队列长度远超均值，整批的首 token 时间被这张卡锁定；此时按路径分桶组批能让长上下文请求独占 EP 组，避免与短请求混跑时的路由抖动。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-38\">三十八 · PP 与 DP：流水线气泡和副本数的取舍</h3>\n<p>PP 把模型按层切到不同卡上，代价是流水线气泡：微批在阶段间流动时，首尾阶段存在空闲。对 Repoformer 的两条路径，PP 的意义不同。检索路径的长上下文预填适合用较大微批填充流水线，气泡占比低；无检索路径的短请求若也走 PP，微批太小、气泡占比高，反而不如 DP 复制整模型。DP 则是把整模型复制多份，每份独立处理请求，通信只发生在梯度同步（推理时无）与负载均衡上，代价是显存按副本数翻倍。Repoformer 的选择器本身是轻量模型，可单独用 DP 复制多份做判定，与生成器的并行拓扑解耦——这正是“选择器与生成器解耦”在并行层面的落地。</p>\n<p>工程判断：显存预算有限时，优先把 DP 副本留给无检索路径（短上下文、KV 占用低，单副本可服务高并发），把 PP/TP 留给检索路径的长上下文。代价体现在显存碎片：两条路径若共享同一组卡，长短上下文混跑会让 KV cache 的块分配在长请求到来时挤占短请求的空间，PP 阶段间的激活缓冲也会因微批大小不一而浪费。例子：无检索路径用 DP=4 复制四份生成器，每份处理短前缀请求，前缀缓存命中率高；检索路径用 PP=2 + TP=4 的组合承载长上下文，两条路径的进程组隔离，避免 DP 副本的显存被长请求的 KV 侵占。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-39\">三十九 · NIXL 传输与分离式预填/解码的通信账</h3>\n<p>分离式预填/解码把预填与解码拆到不同节点，KV cache 需要从预填节点传到解码节点，NIXL 承担这条传输路径。Repoformer 的两条路径在分离式部署下的通信账不同：无检索路径的短前缀 KV 很小，传输开销可忽略，甚至不值得分离；检索路径的长上下文 KV 体积大，传输时间与 KV 字节数除以有效带宽成正比，若传输时间超过解码节点等待的收益，分离就失去意义。机制上，NIXL 支持 RDMA 与 GPU 直连传输，KV 块的布局要与传输粒度对齐，否则零散小块的传输效率低。</p>\n<div class=\"formula\">$$T_{\\text{xfer}} = \\frac{2\\cdot L\\cdot H_{\\text{kv}}\\cdot d_{\\text{bytes}}\\cdot B_{\\text{batch}}}{B_{\\text{rdma}}}$$</div>\n<p>其中 L 为序列长度，H_kv 为 KV 头维度总量，d_bytes 为每元素字节数，B_batch 为批大小。这个式子直接说明：检索路径的长上下文让 T_xfer 随 L 线性增长，而解码节点在此期间处于等待，尾延迟被传输锁定。工程判断是：只在检索路径且 KV 体积超过阈值时才启用分离式，无检索路径留在同节点完成预填与解码；同时按路径分别设定 SLO，检索路径的 SLO 要把传输时间计入。例子：一个长上下文请求在预填节点完成拼接上下文的预填后，KV 经 NIXL 传到解码节点，若传输时间与预填时间同量级，分离的收益被抵消，此时应改为同节点预填解码或缩小拼接预算。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-40\">四十 · 通信何时成为瓶颈：按路径核算的判据</h3>\n<p>通信成为瓶颈的判据不是“有没有集合通信”，而是通信时间与计算时间的比值。对 Repoformer，这个比值在两条路径上符号相反：无检索路径计算量小、序列短，集合通信的固定延迟占比高，任何 TP/EP 都会让通信主导；检索路径计算量大、序列长，集合通信的带宽项占比高，TP/EP 的收益在域内仍然为正，但跨域后跳数延迟叠加，收益转负。可操作的判据是：若单层计算时间小于 All-Reduce 的固定延迟乘以跳数，就不该扩 TP；若 KV 传输时间超过解码节点单步时间乘以等待步数，就不该做分离式。</p>\n<table class=\"mini\"><thead><tr><th>路径</th><th>主导通信</th><th>瓶颈形态</th><th>工程取舍</th></tr></thead><tbody><tr><td>无检索</td><td>TP All-Reduce 固定延迟</td><td>短序列下延迟项主导</td><td>TP=1/2，DP 扩副本，前缀缓存复用</td></tr><tr><td>检索</td><td>TP All-Reduce 带宽 + EP All-to-All</td><td>长序列下带宽项主导，热点卡定尾延迟</td><td>TP/EP 留在 NVSwitch 域内，按路径独占组</td></tr><tr><td>分离式</td><td>NIXL KV 传输</td><td>KV 体积随拼接长度线性增长</td><td>仅检索路径启用，传输时间计入 SLO</td></tr></tbody></table>\n<p>例子：同一台 NVL72 上，无检索路径的请求以 DP=4 跑短前缀，通信几乎为零，吞吐由解码步数决定；检索路径的请求以 TP=8 跑长上下文预填，All-Reduce 在域内带宽项可控，但若拼接预算放大到让 KV 传输时间超过解码单步时间，分离式部署的尾延迟反而高于同节点方案。此时正确的动作是收紧检索预算或改回同节点，而不是继续加 TP。通信瓶颈的最终判据落在“按路径分别核算、按域边界设限”上：域内带宽换 TP 收益，域外跳数延迟换分离式收益，两者都不能跨路径混算。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-41\">四十一 · 选择性检索在并行拓扑上的边界与代价</h3>\n<p>Repoformer 的两条路径在并行切分上并非同构。无检索路径上下文短，单请求的 KV 占用小，TP 组内张量切分带来的 All-Reduce 通信量随隐藏维与批内 token 数线性增长，但因其序列短、批可做大，通信/计算比仍落在可接受区间；检索路径拼接后上下文显著变长，预填阶段的激活与 KV 写入放大，若仍按同一 TP 度切分，单卡显存与 All-Reduce 带宽同时吃紧。工程判断是：两条路径应允许不同的 TP/DP 配比，短路径偏向更大 DP 以提高并发，长路径偏向更大 TP 以摊薄单卡显存，代价是拓扑切换带来的调度复杂度与权重副本冗余。</p>\n<p>用 EP 处理检索路径的稀疏性同样有边界。检索触发率由阈值 τ 决定，触发样本在批内占比低时，EP 的 All-to-All 在专家负载不均下会产生排队，通信时间近似正比于被路由 token 数与单 token 字节数除以链路带宽：</p>\n<div class=\"formula\">$$T_{\\text{a2a}} \\approx \\frac{N_{\\text{routed}}\\cdot b}{B_{\\text{link}}}+T_{\\text{queue}}(\\text{imbalance})$$</div>\n<p>其中 $N_{\\text{routed}}$ 是触发检索后被路由的 token 数。触发率低意味着多数请求走短路径，EP 的收益被闲置的专家容量抵消；触发率高则 All-to-All 成为尾延迟主因。NVLink 5 与 NVSwitch 提供的高带宽只在拓扑内有效，跨节点仍需 NIXL 做 KV 与片段的远程传输，检索路径的上下文重建使这类传输无法靠前缀缓存摊薄。</p>\n<p>PP 与选择性检索的耦合更隐蔽。检索路径的预填长度随召回片段数波动，PP 各 stage 的负载随请求分布漂移，气泡在长上下文请求上被放大；而无检索路径的短请求若与检索请求混批，PP 的流水填充与排空比例失衡。因此按路径分桶组批不只是显存问题，也是通信与流水效率问题。下表给出两条路径的资源特征对比：</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>无检索路径</th><th>检索路径</th></tr></thead><tbody><tr><td>上下文长度</td><td>短、稳定</td><td>随召回与预算截断波动</td></tr><tr><td>主要通信</td><td>TP All-Reduce</td><td>TP All-Reduce + EP All-to-All + NIXL 传输</td></tr><tr><td>KV 复用</td><td>前缀缓存命中率高</td><td>按请求重建，命中率低</td></tr><tr><td>失效条件</td><td>阈值偏低致触发率上升</td><td>召回噪声推高预填与显存</td></tr></tbody></table>\n<p>通信成为瓶颈的判据是：单请求的通信时间超过其计算时间，或批内长上下文请求占比使 All-to-All 排队主导尾延迟。此时降低 τ 以减少检索路径占比、或对检索片段做更激进的预算截断，比提升并行度更有效；反之若 τ 偏高导致漏检关键定义，则质量损失无法用通信优化补偿。</p>\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-42\">四十二 · 精度塌陷：漏检与误检的双向代价</h3>\n<p>Repoformer 的两条路径由选择器阈值 τ 切开，精度塌陷的根源几乎都落在这个二值决策上。漏检（应检索却走无检索路径）表现为补全引用了当前文件未定义、却在别处声明的符号，生成器在短上下文里只能凭参数记忆猜签名，输出语法正确但语义错位的调用；误检（不应检索却触发检索）则把弱相关片段塞进提示，稀释信号并挤占生成长度预算，模型倾向于复制拼接片段里的邻近代码而非完成当前意图。两者在监控上的指纹不同：漏检常伴随编译期未定义符号错误与跨文件符号解析失败率上升，误检则表现为补全与光标前局部上下文的编辑距离异常增大、重复片段增多。</p>\n<p>诊断要落到可观测的量上。对每个请求记录选择器输出 <span>s(x)</span> 与阈值 τ 的差值、实际拼接 token 数、检索片段数与去重后保留数，构成一条决策轨迹。当某仓库的未定义符号错误率抬升而检索触发率同时下降，基本可判定为阈值偏高导致的系统性漏检；反之触发率抬升而补全接受率不升，指向误检与过滤失效。定位手段是分层抽样回放：把 τ 临时下调一档，对同一批请求重跑，比较两次输出的符号解析成功率，若下调后显著改善则确认漏检面。代价上，漏检的代价是质量返工与开发者信任流失，误检的代价直接体现为预填算力与 KV 占用——检索路径的上下文长度显著高于无检索路径，误检等于把短请求人为拉长，抬高了平均上下文长度这一容量规划的关键输入。</p>\n<div class=\"formula\">$$\\text{trigger}(x)=\\mathbb{1}\\big[s(x)\\ge\\tau\\big],\\quad \\mathbb{E}[L]=\\text{trigger}\\cdot \\bar{L}_{ret}+(1-\\text{trigger})\\cdot \\bar{L}_{no}$$</div>\n<p>上式说明平均上下文长度是触发率的线性插值，阈值每下调一点，预填算力与 KV cache 占用就按检索路径与无检索路径的长度差成比例上升。举例：某仓库大量补全集中在单文件内的样板代码，若沿用为跨文件密集仓库标定的 τ，触发率被推高，短请求被迫背上召回与拼接开销，尾延迟随之恶化；此时应按仓库重新标定 τ，而不是全局调参。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-43\">四十三 · OOM 与显存碎片：两条路径混跑的账</h3>\n<p>OOM 在选择性检索部署里很少是单请求超限，更多是批内长短请求混排导致的碎片化。检索路径的拼接上下文可达无检索路径的数倍，若调度器按统一 token 预算组批，一个长请求进入短批就会把该批的激活与 KV 峰值顶到显存档位之上。机制上，KV cache 按层按头分配，长上下文请求的 KV 块尺寸与短请求不同，混批时分配器难以复用空闲块，碎片累积到一定程度触发分配失败。诊断信号是显存分配失败率与批内上下文长度的方差同时上升，而非平均占用率触顶。</p>\n<p>处置分三步：按路径分桶组批，把检索路径与无检索路径放进不同队列，各自按自身长度分布设定批大小上限；对检索路径设单批 token 总预算硬上限，超限请求降级为更小批或单请求执行；对无检索路径启用前缀缓存复用，短前缀命中缓存可显著压低该路径的 KV 重建量。代价权衡明确：分桶会降低批的填充率、牺牲部分吞吐，但换来尾延迟与 OOM 率的可控；前缀缓存只对无检索路径有效，检索路径上下文随请求变化、命中率低，需按请求重建 KV，这部分重建开销必须单独计入容量模型。</p>\n<p>具体例子：一个仓库索引刚更新、缓存失效的时段，检索路径请求集中到达，若与常规短请求混批，显存峰值被长上下文拉高而短请求的批填充率被浪费；分桶后短批保持高填充，长请求单独成小批，显存曲线变平。监控上应把“批内最大上下文长度”与“批内长度方差”作为一等指标，先于 OOM 报警出现。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-44\">四十四 · 批抖动与尾延迟：按路径设 SLO</h3>\n<p>批抖动来自触发率的短时波动。检索触发率不是常数，它随仓库、文件类型与光标位置漂移；当一批请求里检索路径占比突增，调度器若仍按历史平均组批，就会出现批构成剧烈变化，单批执行时间方差放大。尾延迟的放大机制在于：检索路径包含召回、过滤、去重与截断四段串行开销，再叠加长上下文的预填，其 P99 与无检索路径不在同一量级。用统一 SLO 衡量会把两条路径的尾延迟混在一起，掩盖检索路径的真实瓶颈。</p>\n<p>诊断上按路径分别统计 P50/P99 与排队时长，把检索路径的耗时拆成召回、过滤、预填、解码四段，找出占比最高的那段。若召回段占比高，问题在索引查询与候选规模；若预填段占比高，问题在拼接预算与截断策略。伪代码思路：对每条路径维护独立的滑动窗口延迟分布，当某路径 P99 超过其目标值且触发率同向抬升时，自动收紧该路径的批大小上限或临时上调 τ 以降低触发率，形成负反馈。</p>\n<table class=\"mini\"><thead><tr><th>路径</th><th>主要开销段</th><th>抖动来源</th><th>处置</th></tr></thead><tbody><tr><td>无检索</td><td>解码</td><td>批构成变化</td><td>前缀缓存、稳定组批</td></tr><tr><td>检索</td><td>召回+预填</td><td>触发率突增、索引冷启</td><td>独立队列、token 预算硬限、τ 自适应</td></tr></tbody></table>\n<p>代价判断：收紧批大小换尾延迟会牺牲吞吐，上调 τ 换尾延迟会牺牲质量（漏检风险上升），二者不可同时最优，必须按业务 SLO 排优先级。若补全场景对首 token 延迟敏感，宁可牺牲部分检索召回质量也要压住 P99；若对正确性敏感，则接受更长尾延迟并放宽批上限。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-45\">四十五 · 静默降级：没有报错的质量滑坡</h3>\n<p>最危险的失败模式不抛异常。检索索引过期时，召回返回的是旧版本片段，过滤与去重照常通过，拼接照常完成，生成器输出语法合法但引用了已删除的接口；选择器置信度分布整体偏移时，阈值仍按旧分布生效，触发率缓慢漂移而无人察觉。这类降级在日志里全是 200，只在补全接受率与符号解析成功率上留下痕迹。诊断需要把质量指标与决策指标并列监控：检索触发率、平均拼接 token 数、选择器置信度分布、去重后保留片段数、补全接受率、未定义符号错误率，任一指标相对基线漂移超过设定带宽即触发告警。</p>\n<p>定位静默降级的关键是版本对齐：把每次请求的索引版本号、选择器模型版本、阈值配置一并写入轨迹，当质量指标下滑时按这三个维度切片，快速判断是索引过期、选择器漂移还是阈值错配。回滚策略对应三层：索引层回滚到上一快照并触发增量重建；选择器层回滚到上一版本权重或恢复上一组阈值；配置层把 τ 与拼接预算恢复到标定值。回滚必须可灰度，先对单仓库或单流量分片生效，观察触发率与质量指标回归后再全量。</p>\n<p>具体例子：仓库频繁变更时段，增量索引未及时跟上，检索路径召回到已重命名的函数，补全输出调用旧名。监控上未定义符号错误率在检索路径上抬升而无检索路径平稳，切片后索引版本号集中在某一批次，即可判定为索引失效而非选择器问题，回滚索引快照即可，无需动阈值。代价上，索引重建消耗算力与时间，频繁回滚会拖慢索引更新节奏，因此需在索引新鲜度与重建成本之间设阈值，而非每次变更都全量重建。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-46\">四十六 · 监控闭环与工程判断</h3>\n<p>把上述失败模式收进一个闭环：采集层记录决策轨迹与分段耗时；聚合层按路径、按仓库、按版本切片；判定层用漂移检测对比基线与当前窗口；执行层触发分桶调整、τ 自适应或回滚。闭环的关键是把“是否检索”的决策本身当作可观测对象，而不是黑盒。选择器可低比特量化以降低判定开销，但量化会改变置信度分布，进而改变同一 τ 下的触发率，因此量化上线必须重新标定 τ 并纳入漂移监控，否则就是一次静默降级的引入。</p>\n<p>工程判断落在阈值治理上：τ 不应是全局常量，而应按仓库分布标定并周期性复核，触发率作为一等 SLO 指标被持续观测。当触发率与平均拼接 token 数同步抬升而质量指标不升，优先怀疑误检与过滤失效，处置是收紧过滤与下调拼接预算；当触发率下降而符号解析失败率上升，优先怀疑漏检，处置是下调 τ 并回放验证。两条路径的容量规划必须分开核算，检索路径的召回与拼接开销不是免费收益，混批与统一 SLO 是把局部最优误当成全局最优的典型来源。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-47\">四十七 · 双路径的失效边界：从阈值漂移到静默降级</h3>\n<p>选择性检索的收益全部押在选择器的一次二值判断上，因此诊断的第一现场不是生成质量，而是触发率分布。设选择器对第 <i>i</i> 个请求的置信度为 <i>s<sub>i</sub></i>，阈值 τ 决定检索触发率 <i>r</i>(τ)=P(<i>s</i>≥τ)，则平均拼接上下文长度近似为 <i>L̄</i>=(1−<i>r</i>)<i>L<sub>short</sub></i>+<i>r</i>(<i>L<sub>short</sub></i>+<i>B</i>)，其中 B 为检索预算。τ 偏低时 <i>r</i> 抬升，预填算力与 KV 占用按上式线性放大；τ 偏高则漏检跨文件定义，补全退化为局部猜测。关键在于同一 τ 在不同仓库上的 <i>r</i> 差异极大——单文件小仓库几乎全走短路径，多模块仓库则相反，所以 τ 必须按仓库分布标定，并在上线后持续监控 <i>r</i> 的漂移，而不是一设定终身。</p>\n<p>精度塌陷的典型形态是“静默降级”：选择器漏检关键定义，生成器在短上下文上给出语法合法但语义错误的补全，系统既不报错也不触发重试，监控指标上只表现为通过率缓降。定位手段是把请求按“是否触发检索”与“选择器置信度分位”交叉分桶，对比两桶的补全接受率；若低置信桶的接受率显著低于高置信桶，说明阈值切在了错误的分布位置。另一类塌陷来自误检——检索噪声挤占生成长度预算，模型在无关片段上做约束解码，输出幻觉式调用。此时应检查过滤与去重环节的丢弃率，丢弃率骤降往往意味着索引召回质量退化。</p>\n<p>系统侧代价则集中在批调度与显存。两条路径上下文长度差异明显，混批会同时造成显存碎片与尾延迟抬升：短请求被长请求拖住，长请求又因批内短样本填充而浪费算力。工程上应按路径分桶组批，并对检索路径单独设定 SLO，因为其尾延迟天然更高。前缀缓存也要分开核算——无检索路径的短前缀可复用，命中率高；检索路径上下文随请求变化，缓存命中率低、需按请求重建 KV，显存峰值因此上移。OOM 往往不发生在平均负载，而发生在检索触发率突增的窗口，容量规划必须把 <i>r</i> 当作输入参数而非结果。</p>\n<p>回滚策略应做成路径级开关而非整机降级：当监控到检索路径尾延迟越限或显存水位逼近阈值时，先把 τ 临时上调压缩触发率，再视情况关闭检索路径、退回纯无检索模式，保证短路径的稳定吞吐；反之若发现漏检导致的精度塌陷，则下调 τ 并放宽预算 B。仓库索引的构建与更新成本未量化，频繁变更时需设计增量索引与缓存失效，否则陈旧索引会以“相关性过滤丢弃率异常”的形式暴露。诊断顺序建议固定为：触发率漂移→分桶接受率→过滤丢弃率→显存与尾延迟，逐层排除，避免把调度问题误判为模型问题。</p>\n<table class=\"mini\"><thead><tr><th>症状</th><th>首要怀疑</th><th>处置</th></tr></thead><tbody><tr><td>通过率缓降、无报错</td><td>选择器漏检</td><td>下调 τ，分桶比对接受率</td></tr><tr><td>尾延迟抬升、显存峰值上移</td><td>触发率突增或混批</td><td>按路径分桶，上调 τ 压缩触发</td></tr><tr><td>幻觉式调用增多</td><td>检索噪声、过滤失效</td><td>检查丢弃率与索引新鲜度</td></tr></tbody></table>\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-48\">四十八 · 口径先行：把“选择性”拆成可测的四个量</h3>\n<p>Repoformer 的评测口径不能沿用“端到端平均延迟”这一把尺子，因为它的推理管线是两条上下文长度分布完全不同的路径。任何一次基准测试，必须先固定四个量：检索触发率 <em>r</em>（被选择器判为需要检索的样本占比）、无检索路径上下文长度 <em>L₀</em>、检索路径拼接后长度 <em>L₁</em>、以及检索路径的召回与过滤开销 <em>C<sub>ret</sub></em>。平均上下文长度可写成 <em>L̄ = (1−r)·L₀ + r·L₁</em>，而平均预填算力近似正比于 <em>L̄</em> 的平方项（注意力）加线性项（投影与 MLP）。这意味着报告“平均上下文缩短了多少”而不报 <em>r</em> 是没有意义的：<em>r</em> 从 0.2 抬到 0.5，即便 <em>L₁</em> 不变，预填代价也会显著抬升。工程上应把 <em>r</em> 当作一等指标写进监控面板，与选择器置信度分布并列。</p>\n<p>指标集合建议按路径分列：无检索路径报 TTFT、TPOT、前缀缓存命中率；检索路径额外报召回延迟、过滤与去重耗时、拼接 token 数分布。吞吐必须标注组批策略——是按路径分桶还是混批。显存要报两条路径各自的 KV 峰值，因为 <em>L₁</em> 的长尾决定了显存档位，而不是均值。功耗在两条路径上差异来自预填占比：检索路径预填重、解码相对轻，无检索路径则相反，因此同一张卡上两条路径的能效曲线不可混谈。</p>\n<div class=\"formula\">$$\\mathrm{TTFT}\\approx \\frac{L\\cdot d\\cdot 2}{F_{\\text{prefill}}}+t_{\\text{ret}},\\qquad \\mathrm{TPOT}\\approx \\frac{2\\cdot N_{\\text{param}}\\cdot b}{BW_{\\text{HBM}}}$$</div>\n<p>上式中 <em>t<sub>ret</sub></em> 只在检索路径存在，<em>b</em> 为并发批大小。举例：一个仓库级补全请求若 <em>L₀</em> 只有数百 token，TTFT 基本由固定开销主导；一旦触发检索把上下文拉到数千 token，TTFT 的注意力项迅速变成主项，而此时 <em>t<sub>ret</sub></em> 又叠加在关键路径上。因此“选择性检索降低延迟”这一说法只在 <em>r</em> 较低且 <em>L₁</em> 被预算截断得住时成立，报告必须给出 <em>r</em> 与 <em>L₁</em> 的实际分布，否则读者无法判断收益来自哪里。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-49\">四十九 · 硬件档位与 batch：两条路径不能共用一张组批表</h3>\n<p>材料未给出硬件档位，这本身就是口径问题：同一份选择性检索策略在 B200 单卡、GB200 NVL72 机架、以及不同显存容量档位上表现不同，因为 <em>L₁</em> 的长尾决定能否装下目标并发。基准报告应写明加速器型号、显存容量、互联形态（单卡 / NVLink 域内 / 跨节点），以及是否启用分离式预填解码。若使用分离式部署，检索路径的重预填应落在预填池，无检索路径的短请求可留在解码池就近处理，此时 TTFT 的口径要区分“预填池排队时间”与“解码池首 token 时间”，不能合并成一个数。</p>\n<p>batch 与并发是第二个不可比的来源。两条路径混批时，一个 <em>L₁</em> 达数千 token 的请求会把整批的 KV 峰值拉高，短请求被迫按长请求的显存档位分配，显存碎片与尾延迟同时抬升。正确做法是按路径分桶组批，桶内再按长度分档。连续批处理下，桶的填充率决定吞吐：无检索桶可以塞很高的并发，检索桶受 <em>L₁</em> 与 KV 预算约束，并发上限低得多。报告吞吐时必须同时给出每桶的并发数与填充率，否则“tokens/s”这个数字在不同组批策略下相差数倍。</p>\n<table class=\"mini\"><thead><tr><th>口径项</th><th>无检索路径</th><th>检索路径</th></tr></thead><tbody><tr><td>上下文长度</td><td>短、方差小</td><td>长、长尾明显</td></tr><tr><td>关键延迟项</td><td>固定开销 + 解码</td><td>召回 + 预填 + 解码</td></tr><tr><td>KV 复用</td><td>前缀缓存命中率高</td><td>按请求重建，命中率低</td></tr><tr><td>组批约束</td><td>高并发、填充率高</td><td>受 KV 预算限，并发低</td></tr></tbody></table>\n<p>具体例子：若把无检索桶的并发设为 <em>b₀</em>、检索桶设为 <em>b₁</em>，且 <em>b₁ ≪ b₀</em>，则整体吞吐近似 <em>(1−r)·b₀ + r·b₁</em> 的加权，抬升 <em>r</em> 会直接压低总吞吐，即便单请求质量提升。这条算术关系应在容量规划阶段就写进模型，而不是等实测发现吞吐掉了再回头找原因。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-50\">五十 · 指标怎么读：TTFT/TPOT 的分母是谁</h3>\n<p>TTFT 与 TPOT 在选择性检索场景下最容易读错，因为分母（请求集合）本身被选择器改变了。若报告只统计“触发了检索的请求”的 TTFT，会得到一个偏差极大的数；若只统计全部请求的均值，又会掩盖检索路径的长尾。规范做法是三条曲线并列：全体请求的 TTFT 分布、按路径分列的分位数（p50/p90/p99）、以及以 <em>r</em> 为横轴的敏感性曲线。TPOT 同理，检索路径因上下文长、注意力开销大，其 TPOT 通常高于无检索路径，但解码阶段的 token 生成速率未必更低——差异主要来自每步注意力的 KV 读取带宽，而非参数带宽。</p>\n<p>吞吐的口径要区分“请求吞吐”与“token 吞吐”。选择性检索降低了平均上下文长度，token 吞吐可能上升，但请求吞吐受检索路径的召回与过滤串行开销拖累。二者不可互换引用。显存口径要报峰值而非均值，因为 <em>L₁</em> 的长尾决定 OOM 风险；若报告只给平均 KV 占用，读者会误判可承载并发。功耗口径应绑定测量窗口：预填密集的检索路径在短窗口内功耗尖峰高，长窗口均值反而可能低于持续解码的无检索路径。</p>\n<div class=\"formula\">$$\\text{有效吞吐}=\\frac{N_{\\text{req}}}{\\sum_i \\mathrm{TTFT}_i+\\sum_i (n_i-1)\\cdot \\mathrm{TPOT}_i}$$</div>\n<p>举例：两个系统报告相同的 tokens/s，但一个 <em>r</em>=0.1、<em>L₁</em> 被截断在较小预算，另一个 <em>r</em>=0.4、<em>L₁</em> 长尾严重；前者靠高并发短请求堆出吞吐，后者靠长上下文摊薄固定开销，二者的 SLO 达标率完全不同。因此任何吞吐数字必须附 <em>r</em>、<em>L₁</em> 分布与组批策略三要素，缺一不可比。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-51\">五十一 · 哪些提升不可比：五类常见错位</h3>\n<ul>\n<li><strong>基线错位。</strong>把“固定窗口检索”与“全量拼接”当作同一基线引用，但两者上下文长度差一个量级，预填代价不可直接相减。选择性检索的收益应分别对这两条基线核算，而不是取一个混合基线。</li>\n<li><strong>触发率未标注。</strong>不同阈值下 <em>r</em> 不同，平均上下文与吞吐随之变化；不标 <em>r</em> 的“延迟降低 X%”无法复现，也无法判断是否以漏检为代价。</li>\n<li><strong>混批与分桶混用。</strong>分桶组批的吞吐天然高于混批，若一方分桶一方混批，比较的是调度策略而非检索策略。</li>\n<li><strong>缓存状态不同。</strong>无检索路径可复用前缀缓存，检索路径按请求重建 KV；一方开缓存一方关缓存，TTFT 差异会被误读为检索开销。</li>\n<li><strong>质量口径缺失。</strong>材料未给出通过率与评测口径，任何“质量提升”都无法与上下文成本做联合比较；只能定性说选择性检索在质量与成本间取折中。</li>\n</ul>\n<p>这五类错位的共同点是：它们都改变了分母或路径混合比例，而报告只给了分子。工程判断上，看到任何一个端到端数字，先问三件事——<em>r</em> 是多少、两条路径是否分开统计、组批与缓存状态是否一致。答不上来，这个数字就不能进容量模型。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-52\">五十二 · 阈值标定的实测口径：把选择器当被测件</h3>\n<p>选择器阈值 <em>τ</em> 是整套口径的枢纽，因此基准必须把选择器本身当作被测件，而不是当作给定条件。可测的量包括：触发率 <em>r(τ)</em> 随 <em>τ</em> 的曲线、误检率（本可自足却被判需检索）与漏检率（需要跨文件定义却被判自足）。误检的代价是预填算力与显存，漏检的代价是补全错误，两者量纲不同，不能合成一个“准确率”。工程上应按仓库分别标定：同一 <em>τ</em> 在不同仓库分布上触发率差异大，需持续监控 <em>r</em> 的漂移。</p>\n<div class=\"formula\">$$\\mathbb{E}[\\text{cost}]=(1-r)\\cdot c_0+r\\cdot(c_1+c_{\\text{ret}})+\\lambda\\cdot\\big(p_{\\text{miss}}\\cdot c_{\\text{err}}\\big)$$</div>\n<p>上式给出一个可操作的标定思路：把误检成本（<em>c₁+c<sub>ret</sub></em> 相对 <em>c₀</em> 的增量）与漏检的错误成本用系数 <em>λ</em> 加权，扫 <em>τ</em> 找极小点。举例：若某仓库的补全以局部自足样本为主，抬高 <em>τ</em> 压低 <em>r</em> 能显著降预填；若该仓库跨文件引用密集，压低 <em>τ</em> 换质量则要接受 KV 峰值上移与并发下降。这个权衡必须按仓库实测，材料未给出任何阈值数值，落地时不得引用外部数字。</p>\n<p>监控项应固定为：<em>r</em>、平均拼接 token 数、选择器置信度分布、两条路径各自的 p99 TTFT、检索路径 KV 峰值、前缀缓存命中率。任何一项漂移都意味着口径失效，需要重新标定而非直接套用旧容量模型。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-53\">五十三 · 索引与缓存成本：不进延迟口径就会漏账</h3>\n<p>检索路径的召回依赖仓库索引，索引构建与更新成本材料未量化，但它直接决定检索路径的可用性与 <em>t<sub>ret</sub></em> 的稳定性。仓库频繁变更时，缓存失效与增量索引策略缺失会让 <em>t<sub>ret</sub></em> 出现长尾，进而污染检索路径的 TTFT 分位数。基准报告应把索引新鲜度作为口径变量：索引滞后时召回质量下降，选择器的判定与过滤器的相关性打分都会受影响，此时测得的 <em>r</em> 与质量不可与新鲜索引下的结果并列。</p>\n<p>前缀缓存的口径同样要分开：无检索路径的短前缀命中率高，KV 复用直接压低 TTFT；检索路径因上下文随请求变化，缓存命中率低，需按请求重建 KV，其显存峰值与重建耗时都应单独计量。若报告把两条路径的缓存命中率合并成一个数，读者会高估整体复用收益。工程判断上，选择性检索的净收益等于“无检索路径省下的预填与 KV”减去“检索路径新增的召回、过滤、拼接与重建成本”，再按 <em>r</em> 加权；这个减法必须在同一硬件档位、同一组批策略、同一缓存状态下完成，否则数字不可比。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-54\">五十四 · 基准口径：两条路径不能共用一把尺</h3>\n<p>Repoformer 的评测口径必须先拆成两条路径再谈数字：无检索路径的上下文短、预填算力低、KV 占用小；检索路径要额外承担召回、相关性过滤、去重与预算截断的算力与延迟，且拼接后上下文长度随请求变化。把两条路径混在一个平均值里报吞吐或 TTFT，等于把召回开销摊到短请求上，读数失真。工程上应按路径分别统计触发率 <span class=\"formula\">$$r=\\frac{N_{\\text{ret}}}{N_{\\text{total}}}$$</span> 与平均拼接 token 数 <span class=\"formula\">$$\\bar{L}=r\\cdot L_{\\text{ret}}+(1-r)\\cdot L_{\\text{none}}$$</span>，后者才是容量规划里 KV cache 与预填算力的真实输入；<span class=\"formula\">$$r$$</span> 漂移一个百分点，显存档位与 batch 上限就要重算。</p>\n<p>硬件档位与量化方案材料未给出，因此任何跨档位的“提升”都不可比：选择器若做低比特量化，判定开销下降但误判率上升，误检会把短请求推入检索路径，直接抬高 <span class=\"formula\">$$\\bar{L}$$</span> 与预填代价；生成器精度则需单独评估，不能与选择器共用一套量化结论。指标上，TTFT 应分路径看——无检索路径的短前缀适合前缀缓存复用，TTFT 主要由调度排队决定；检索路径因上下文随请求变化，缓存命中率低、需按请求重建 KV，TTFT 里混入了召回与拼接的串行段。TPOT 与吞吐则受组批形态支配：两条路径混批会同时造成显存碎片与尾延迟抬升，按路径分桶组批后，短请求桶可以吃满 batch，检索桶则受最长上下文约束。</p>\n<p>哪些提升不可比，需要一张口径表钉死：</p>\n<table class=\"mini\"><thead><tr><th>读数</th><th>可比条件</th><th>不可比情形</th></tr></thead><tbody><tr><td>平均上下文长度</td><td>同一阈值 τ、同一仓库分布</td><td>阈值不同或仓库变更频繁，触发率漂移</td></tr><tr><td>TTFT / TPOT</td><td>同路径、同 batch 上限、同档位</td><td>长短混批、跨显存档位、缓存命中率不同</td></tr><tr><td>吞吐</td><td>分路径组批且 SLO 一致</td><td>把召回开销摊进短请求平均值</td></tr><tr><td>显存 / 功耗</td><td>同一 <span class=\"formula\">$$\\bar{L}$$</span> 与并发数</td><td>仅报峰值显存、不报检索桶尾延迟</td></tr></tbody></table>\n<p>边界与失效条件集中在选择器误判：漏检跨文件定义会让补全缺关键符号，误检则引入噪声并额外付出预填与显存代价，两类错误在指标上表现相反——前者伤质量、后者伤成本，不能用一个准确率概括。阈值 τ 与仓库分布强耦合，同一 τ 在不同仓库上触发率差异大，需按仓库标定并持续监控置信度分布；仓库索引的构建与更新成本未量化，频繁变更时缓存失效与增量索引策略缺失，会让检索路径的尾延迟进一步恶化。因此本方案的收益必须与无检索基线、固定检索基线在同一口径下分路径核算，材料未给出可核验的通过率、延迟或吞吐数字，落地时以自测的 <span class=\"formula\">$$r$$</span>、<span class=\"formula\">$$\\bar{L}$$</span> 与分路径尾延迟作为验收口径，而不是引用任何跨档位的提升幅度。</p>\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-55\">五十五 · 迁移到别的代码模型：解耦带来的可移植性与其代价</h3>\n<p>Repoformer 的两阶段结构里，选择器与生成器是解耦的，这一点决定了它迁移到别的代码模型时的主要工作量分布。生成器替换相对直接：只要新模型接受“局部窗口”与“局部窗口⊕过滤后片段”两种输入形态，并保持相同的约束解码接口，替换不改动管线拓扑。真正要重做的是选择器的输入表征与阈值标定——选择器吃的是光标前缀与局部窗口，不同模型的 tokenizer 切分方式不同，同一段代码在 Code Llama 系与 CodeT5+ 系下的 token 序列长度与边界都不一样，选择器若按 token 数截窗，切分差异会直接改变判定分布。迁移时要么把选择器输入改成字符级或 AST 级窗口以规避 tokenizer 耦合，要么针对新 tokenizer 重新标定窗口长度与阈值 τ。</p>\n<p>代价体现在两处。其一是标定成本：τ 决定检索触发率 r，而平均上下文长度近似为 <span class=\"formula-inline\">L̄ = (1−r)·L_local + r·(L_local + L_ret)</span>，其中 L_ret 是过滤截断后的片段预算。换模型后 L_local 与 L_ret 的可行区间变化，r 必须重扫一遍才能把 L̄ 压回显存档位之内。其二是精度耦合：选择器若用低比特量化以降低判定开销，量化误差会抬高误判率，而误判在两条路径上的代价不对称——漏检丢关键定义，误检多付一次预填。迁移到参数规模更小的生成器时，模型对噪声上下文的鲁棒性更差，误检的边际伤害被放大，此时宁可把 τ 调高、让更多样本走无检索路径。工程判断是：换生成器必须重标 τ，不能沿用原阈值；换 tokenizer 必须重设窗口口径。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-56\">五十六 · 跨领域迁移：检索信号从“定义”变成“惯例”时失效</h3>\n<p>Repoformer 的选择器学的是“这个样本是否需要跨文件信息”，其隐含假设是仓库内存在可被检索命中的显式定义——函数签名、类型声明、导入路径。这套假设在代码补全内部成立，迁到别的领域则要逐条检验。迁到配置与基础设施代码（YAML、Terraform、Helm chart）时，跨文件依赖表现为变量引用与模块输出，检索命中的是键值对而非可编译定义，相关性过滤的打分函数需要重做，否则去重逻辑会把语义不同但字面相似的键误删。迁到查询语言（SQL、DSL）时，跨文件信息往往在 schema 与视图定义里，检索粒度应从“代码片段”改为“schema 条目”，预算截断的单位也随之变化。</p>\n<p>更硬的边界在非代码领域。若把该管线迁到文档问答或工单补全，选择器判定的“自足性”不再由语法结构支撑，而由语义完整性支撑，二值决策的置信度分布会明显偏移，低置信样本比例上升，导致两条路径的组批比例失衡。此时按路径分桶组批的收益被侵蚀：无检索路径的批变小、检索路径的批变大，尾延迟由检索路径主导。可操作的迁移做法是把二值决策放宽为三档（无检索、轻检索、重检索），用预算档位代替单一 τ，代价是调度复杂度上升、需要维护三条组批队列。若领域内不存在稳定的仓库级索引（例如仓库变更频率高于索引重建周期），检索路径的召回质量无法保证，这套方案不适用，应退回固定窗口方案。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-57\">五十七 · 规模上限：触发率与索引新鲜度决定天花板</h3>\n<p>这套方案的上限不在生成器，而在检索路径的两个参数：触发率 r 与索引新鲜度。吞吐侧的约束可以写成粗粒度关系：设单请求平均预填 token 为 L̄，则预填总算力随并发数线性增长，而检索路径还要额外承担召回打分与过滤的算力，这部分与候选集大小成正比。当 r 上升，系统从“短上下文高并发”滑向“长上下文低并发”，KV cache 占用随 L̄ 上升，显存档位成为硬约束。容量规划的关键输入就是 r 的分布而非均值——r 的方差大意味着同一显存档位下需要按高分位预留，实际利用率下降。</p>\n<p>索引侧的上限更隐蔽。仓库频繁变更时，索引重建与增量更新成本未被量化，缓存失效策略缺失意味着检索路径可能命中过期片段，把错误定义拼进上下文，这类错误比漏检更难诊断，因为生成结果语法正确但语义偏离。规模上限的工程判断是：当仓库日变更文件比例高到增量索引追不上请求速率时，检索路径的有效召回率下降，选择性检索退化为随机检索，此时应关闭检索路径或降级为固定窗口。另一个上限来自选择器本身：仓库规模增大后，局部窗口与跨文件依赖的关联变稀疏，选择器在相同 τ 下的判别力下降，需要更多训练信号或更强的输入表征，材料未给出该方向的扩展方案，落地时只能靠监控触发率漂移来发现。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-58\">五十八 · 与低延迟机制的联合边界：前缀缓存与投机解码的适配条件</h3>\n<p>无检索路径的短前缀适合前缀缓存复用，这一点在批调度层面已经成立；但迁移到带投机解码的部署形态时，两条路径的适配性不同。投机解码依赖草稿模型与目标模型对同一上下文的分布一致性，检索路径的上下文随请求变化、缓存命中率低，草稿模型的接受率在长且噪声多的上下文上通常下降，投机收益被抵消。因此投机解码应优先绑定无检索路径，检索路径维持常规解码或仅在过滤后片段质量高时启用。代价是调度器要维护两套解码配置，按路径分派，混用会让尾延迟不可预测。</p>\n<p>前缀缓存的边界同样清晰：检索路径因上下文随请求重建 KV，缓存命中率低，若强行复用会引入跨请求的上下文污染。可操作的做法是把缓存键绑定到“局部窗口哈希 + 过滤后片段哈希”，命中则复用，未命中则重建，代价是哈希计算与缓存查找的额外开销，收益只在同一文件被连续编辑时显现。迁移到分离式预填/解码架构时，检索路径的预填阶段更长，预填与解码的资源配比需按路径分别设定，统一配比会让检索路径的解码实例空转。这些联合评估在材料中缺失，落地时需自行做路径级消融，不能假设选择性检索与低延迟机制叠加即得免费收益。</p>\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-59\">五十九 · 不适用的场景与判断清单</h3>\n<p>有三类场景应明确判定为不适用或需改造后再用。第一类是单文件、无跨文件依赖的补全任务：此时选择器几乎恒判自足，检索路径空转，管线退化为无检索基线，引入选择器只增加判定开销与误判风险，直接去掉选择器更省。第二类是仓库索引不可维护的场景：索引构建与更新成本未量化，若仓库规模大且变更频繁，维护索引的算力与存储代价可能超过检索带来的预填节省，此时应退回固定窗口并按窗口长度做容量规划。第三类是 SLO 极紧的交互式补全：检索路径的召回、过滤与拼接引入额外延迟，尾延迟高于无检索路径，若 SLO 按统一阈值设定，检索路径会持续违约；必须按路径分别设定目标，否则要么整体放宽 SLO 牺牲体验，要么砍掉检索路径牺牲质量。</p>\n<p>判断清单可归结为四个可测输入：检索触发率 r 的分布、平均拼接 token 数 L̄、索引新鲜度（增量更新延迟与请求速率的比值）、以及选择器置信度分布的漂移。四者中任一越界，就应触发阈值重标或路径降级，而不是靠调大显存档位硬扛。迁移到新模型或新领域时，先在这四个量上做小样本标定，再决定是否启用检索路径——这套方案的价值在于把上下文长度变成可控变量，而可控的前提是这些变量被持续测量，否则选择性检索只是把全量拼接的显存问题换成了误判与索引维护的延迟问题。</p>\n\n\n<h3 id=\"paper-repoformer-selective-retrieval-for-r-2024-sec-60\">六十 · 迁移与边界：换模型、换仓库、换负载时要动什么</h3>\n<p>把选择性检索迁到别的代码模型上，最先要改的不是生成器而是选择器的接口契约。选择器吃的是光标前缀加局部窗口，输出二值决策与置信度；换模型后 tokenizer 变了，同一段局部窗口的 token 数随之变化，<span class=\"formula\">$$L_{\\text{eff}}=\\lceil \\tfrac{n_{\\text{chars}}}{\\rho_{\\text{tok}}}\\rceil$$</span> 中的每字符 token 密度 ρ<sub>tok</sub> 若上升，无检索路径的预填算力与 KV 占用会同步抬升，阈值 τ 必须按新 tokenizer 重新标定，否则原本判为自足的样本会被迫走检索路径。生成器侧的约束解码与上下文预算 B 也要重算：B 是拼接后总 token 上限，换模型后同一 B 对应的实际代码片段数下降，过滤与去重的截断策略需从“按片段数”改为“按 token 预算”分配。这一步不做，迁移后触发率与平均上下文长度会同时漂移，容量规划输入失真。</p>\n<p>领域迁移的失效条件集中在仓库分布上。同一 τ 在不同仓库的触发率差异大：单文件小仓库里跨文件定义少，低触发率是正常的；大型单体仓库里符号分散，漏检代价高，τ 需下调。可推断的风险是选择器误判——漏检导致缺关键定义、补全语法正确但语义错，误检则引入噪声并推高预填与显存代价。工程判断是：把 τ 当作按仓库标定的运维参数而非模型常数，持续监控触发率、平均拼接 token 数与选择器置信度分布三条曲线；置信度分布若向 τ 附近聚集，说明决策边界不稳，应扩大局部窗口或引入更强的选择器特征，而不是简单调阈值。仓库频繁变更时索引的构建与更新成本未被量化，缓存失效与增量索引策略缺失，这是规模上限的第一个硬约束：索引新鲜度跟不上提交节奏，检索路径的召回质量会系统性退化。</p>\n<p>规模上限的第二个约束在批调度与缓存。两条路径上下文长度差异明显，必须按路径分桶组批；混批会造成显存碎片与尾延迟抬升，统一 SLO 在并发场景下不成立，检索路径尾延迟更高，SLO 应按路径分别设定。无检索路径的短前缀适合前缀缓存复用，检索路径因上下文随请求变化，缓存命中率低、需按请求重建 KV，因此整体缓存收益随触发率上升而下降。容量规划的关键输入是触发率 r 与两条路径的平均上下文长度：<span class=\"formula\">$$\\bar{L}=r\\,\\bar{L}_{\\text{ret}}+(1-r)\\,\\bar{L}_{\\text{noretr}}$$</span> 平均 KV 占用与预填算力近似正比于该值，r 偏低推高预填成本，r 偏高则漏检风险上升。表里给出迁移时的判断口径：</p>\n<table class=\"mini\"><thead><tr><th>迁移维度</th><th>必改项</th><th>不适用/失效条件</th></tr></thead><tbody><tr><td>换代码模型</td><td>按新 tokenizer 重标 τ 与 B</td><td>token 密度大幅变化时旧阈值失效</td></tr><tr><td>换仓库分布</td><td>按仓库标定 τ、监控误判率</td><td>索引更新跟不上变更节奏</td></tr><tr><td>换负载形态</td><td>按路径分桶组批、分路径 SLO</td><td>高并发混批、统一 SLO 场景</td></tr><tr><td>低比特量化</td><td>选择器可低比特、生成器单独评估</td><td>量化后判定准确率未验证前不适用</td></tr></tbody></table>\n<p>最后一条边界是机制联合评估的缺失：材料未给出与投机解码、前缀缓存等低延迟机制的联合评估，也未给出量化方案与硬件档位。判断是：选择性检索的收益不是免费的，检索路径的召回、过滤与拼接都有算力与延迟代价，必须与无检索路径分开核算；在未标定 τ、未验证选择器量化精度、未设计索引增量更新之前，这套方案只适合作为上下文预算的可控变量接入，而不是当作默认开启的加速开关。</p>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Repoformer: Selective </text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Retrieval for Rep…</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2024 · arXiv preprint</text></svg><figcaption><b>家谱</b> · Repoformer: Selective R… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>仓库级代码补全基准（材料未给出具体数据集名称与规模）</td></tr><tr><td>基线</td><td>固定检索基线、无检索基线</td></tr><tr><td>主要结果</td><td>材料未给出可核验的通过率、延迟或吞吐数字，仅能确认论文主张选择性检索在质量…</td></tr><tr><td>消融</td><td>材料未给出消融实验细节，无法确认选择器、过滤与预算截断各自的贡献比例。</td></tr><tr><td>局限</td><td>材料未给出失败模式与消融的量化结果；可推断的风险包括选择器误判导致漏检关键…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-repoformer-selective-retrieval-for-r-2024 · 共 9 个片段</p>\n";break;}}})();
